//! OSD Telemetry Decoder (Record Type 1).
//!
//! Provides zero-allocation, strongly-typed decoding of instantaneous aircraft position,
//! altitude, velocities, Euler attitudes, flight controller state machine, and status flags.

use byteorder::{ByteOrder, LittleEndian};

use crate::error::{FlightReaderError, Result};

/// Telemetry record type identifier for OSD packets.
pub const RECORD_TYPE: u8 = 1;

/// Minimum payload length in bytes for OSD telemetry records.
pub const MIN_OSD_PAYLOAD_LEN: usize = 53;

/// Multiplicative conversion factor from radians to decimal degrees ($180.0 / \pi$).
pub const RAD_TO_DEG: f64 = 180.0 / std::f64::consts::PI;

/// Ground contact status.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum GroundState {
    /// Aircraft is airborne.
    Airborne = 0,
    /// Aircraft is resting on ground surface.
    OnGround = 1,
    /// Aircraft is currently executing landing touchdown sequence.
    Landing = 2,
    /// Unrecognized or transient ground state.
    Unknown = 3,
}

impl GroundState {
    /// Constructs `GroundState` from raw 2-bit value.
    #[inline]
    pub const fn from_bits(val: u8) -> Self {
        match val & 0x03 {
            0 => Self::Airborne,
            1 => Self::OnGround,
            2 => Self::Landing,
            _ => Self::Unknown,
        }
    }
}

/// Return-To-Home automated navigation status.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum GoHomeStatus {
    /// RTH standby / inactive.
    Standby = 0,
    /// Ascending to configured RTH cruising altitude.
    PreAscending = 1,
    /// Aligning aircraft heading toward Home Point.
    Aligning = 2,
    /// Cruising along direct vector toward Home Point.
    Cruising = 3,
    /// Braking over Home Point target coordinates.
    Braking = 4,
    /// Hovering directly overhead Home Point before descent.
    Overhead = 5,
    /// Performing vertical descent onto landing surface.
    Descending = 6,
    /// Other / vendor-extended status code.
    Other(u8),
}

impl GoHomeStatus {
    /// Constructs `GoHomeStatus` from raw 3-bit value.
    #[inline]
    pub const fn from_bits(val: u8) -> Self {
        match val & 0x07 {
            0 => Self::Standby,
            1 => Self::PreAscending,
            2 => Self::Aligning,
            3 => Self::Cruising,
            4 => Self::Braking,
            5 => Self::Overhead,
            6 => Self::Descending,
            other => Self::Other(other),
        }
    }
}

/// Flight controller navigation and control mode enumeration.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum FlightMode {
    /// Manual flight mode.
    Manual = 0,
    /// Attitude stabilization mode (Atti).
    Atti = 1,
    /// Attitude stabilization with Course Lock.
    AttiCourseLock = 2,
    /// Attitude stabilization in stationary hover.
    AttiHover = 3,
    /// GNSS stationary hover.
    Hover = 4,
    /// GNSS automated braking.
    GpsBrake = 5,
    /// Positioning GNSS mode (P-GPS).
    PGps = 6,
    /// GNSS mode with Course Lock heading hold.
    GpsCourseLock = 7,
    /// GNSS mode with Home Lock heading hold.
    GpsHomeLock = 8,
    /// Point of Interest orbital circle navigation.
    GpsPoi = 9,
    /// Manual takeoff maneuver.
    ManualTakeoff = 10,
    /// Automated takeoff sequence.
    AutoTakeoff = 11,
    /// Automated landing sequence.
    AutoLanding = 12,
    /// Attitude mode landing sequence.
    AttiLanding = 13,
    /// Autonomous waypoint mission execution.
    Waypoints = 14,
    /// Automated Return-to-Home navigation.
    GoHome = 15,
    /// Click-to-Go tap navigation.
    ClickGo = 16,
    /// Virtual joystick / SDK stick control.
    Joystick = 17,
    /// GNSS attitude control via companion wristband.
    GpsAttiWristband = 18,
    /// Cinematic mode with dampened controls.
    Cinematic = 19,
    /// Limited attitude mode.
    AttiLimited = 23,
    /// Draw-based trajectory following.
    Draw = 24,
    /// Pilot target follow-me tracking.
    FollowMe = 25,
    /// Computer-vision ActiveTrack subject tracking.
    ActiveTrack = 26,
    /// Screen tap navigation (TapFly).
    TapFly = 27,
    /// Automated panoramic capture rotation.
    Pano = 28,
    /// Agricultural spraying / mapping pattern.
    Farming = 29,
    /// First-person view acrobatic flight.
    Fpv = 30,
    /// High-performance Sport mode (S-mode).
    Sport = 31,
    /// Beginner training flight mode with spatial constraints.
    Beginner = 32,
    /// Confirmation dialog landing hover.
    ConfirmLanding = 33,
    /// Ground radar terrain following.
    TerrainFollow = 35,
    /// Gesture-based palm control.
    PalmControl = 36,
    /// QuickShot automated cinematic maneuver.
    QuickShot = 37,
    /// Tripod mode with low maximum velocities for photography.
    Tripod = 38,
    /// ActiveTrack spotlight subject lock.
    ActiveTrackSpotlight = 39,
    /// Motor spool-up startup sequence.
    StartingMotors = 41,
    /// Positioning mode with APAS obstacle bypass.
    PGpsBypass = 43,
    /// Timelapse / hyperlapse automated translation.
    Timelapse = 46,
    /// Point of Interest circle orbit.
    Poi = 50,
    /// Smart track subject tracking.
    SmartTrack = 51,
    /// Emergency motor cutoff landing.
    MotorStopLanding = 52,
    /// Pre-manual arming state.
    PreManual = 53,
    /// Normal flight mode (N-mode).
    Normal = 54,
    /// Alternate sport mode variant.
    SportAlternate = 55,
    /// MasterShots multi-shot automated trajectory.
    MasterShots = 58,
    /// Unmapped or vendor-extended flight mode code.
    Other(u8),
}

impl FlightMode {
    /// Constructs `FlightMode` from raw byte.
    #[inline]
    pub const fn from_u8(val: u8) -> Self {
        match val {
            0 => Self::Manual,
            1 => Self::Atti,
            2 => Self::AttiCourseLock,
            3 => Self::AttiHover,
            4 => Self::Hover,
            5 => Self::GpsBrake,
            6 => Self::PGps,
            7 => Self::GpsCourseLock,
            8 => Self::GpsHomeLock,
            9 => Self::GpsPoi,
            10 => Self::ManualTakeoff,
            11 => Self::AutoTakeoff,
            12 => Self::AutoLanding,
            13 => Self::AttiLanding,
            14 => Self::Waypoints,
            15 => Self::GoHome,
            16 => Self::ClickGo,
            17 => Self::Joystick,
            18 => Self::GpsAttiWristband,
            19 => Self::Cinematic,
            23 => Self::AttiLimited,
            24 => Self::Draw,
            25 => Self::FollowMe,
            26 => Self::ActiveTrack,
            27 => Self::TapFly,
            28 => Self::Pano,
            29 => Self::Farming,
            30 => Self::Fpv,
            31 => Self::Sport,
            32 => Self::Beginner,
            33 => Self::ConfirmLanding,
            35 => Self::TerrainFollow,
            36 => Self::PalmControl,
            37 => Self::QuickShot,
            38 => Self::Tripod,
            39 => Self::ActiveTrackSpotlight,
            41 => Self::StartingMotors,
            43 => Self::PGpsBypass,
            46 => Self::Timelapse,
            50 => Self::Poi,
            51 => Self::SmartTrack,
            52 => Self::MotorStopLanding,
            53 => Self::PreManual,
            54 => Self::Normal,
            55 => Self::SportAlternate,
            58 => Self::MasterShots,
            other => Self::Other(other),
        }
    }
}

/// RC hardware flight mode toggle switch physical position.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum ModeChannel {
    /// P-mode (Positioning).
    Position = 0,
    /// S-mode (Sport).
    Sport = 1,
    /// A-mode (Attitude / Manual).
    Attitude = 2,
    /// Unrecognized channel state.
    Unknown(u8),
}

impl ModeChannel {
    /// Constructs `ModeChannel` from 2-bit integer.
    #[inline]
    pub const fn from_bits(val: u8) -> Self {
        match val & 0x03 {
            0 => Self::Position,
            1 => Self::Sport,
            2 => Self::Attitude,
            other => Self::Unknown(other),
        }
    }
}

/// Smart battery pack architecture classification.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum BatteryType {
    /// Standard non-smart LiPo pack without BMS data bus.
    NonSmart = 0,
    /// Single DJI intelligent flight battery with integrated BMS.
    Smart = 1,
    /// Dual smart battery configuration (e.g. Inspire 2, Matrice 300).
    Dual = 2,
    /// Unrecognized battery configuration.
    Unknown(u8),
}

impl BatteryType {
    /// Constructs `BatteryType` from 2-bit integer.
    #[inline]
    pub const fn from_bits(val: u8) -> Self {
        match val & 0x03 {
            0 => Self::NonSmart,
            1 => Self::Smart,
            2 => Self::Dual,
            other => Self::Unknown(other),
        }
    }
}

/// High-level automated flight action state.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum FlightAction {
    /// No automated flight action active.
    None = 0,
    /// Automated takeoff in progress.
    AutoTakeoff = 1,
    /// Automated landing in progress.
    AutoLanding = 2,
    /// Return to Home in progress.
    ReturnToHome = 3,
    /// Other action state.
    Other(u8),
}

impl FlightAction {
    /// Constructs `FlightAction` from raw byte.
    #[inline]
    pub const fn from_u8(val: u8) -> Self {
        match val {
            0 => Self::None,
            1 => Self::AutoTakeoff,
            2 => Self::AutoLanding,
            3 => Self::ReturnToHome,
            other => Self::Other(other),
        }
    }
}

/// OSD flight state bitmask wrapper (Byte 30).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct OsdFlyState {
    /// Raw byte 30 bitmask value.
    pub raw: u8,
}

impl OsdFlyState {
    /// Creates a new `OsdFlyState` view from raw byte.
    #[inline]
    pub const fn new(raw: u8) -> Self {
        Self { raw }
    }

    /// Whether Intelligent Orientation Control (IOC) is available (Bit 0).
    #[inline]
    pub const fn can_ioc_work(&self) -> bool {
        (self.raw & 0x01) != 0
    }

    /// Ground contact state (Bits 1..=2).
    #[inline]
    pub const fn ground_state(&self) -> GroundState {
        GroundState::from_bits((self.raw >> 1) & 0x03)
    }

    /// Whether propulsion motors are armed and spinning (Bit 3).
    #[inline]
    pub const fn is_motor_up(&self) -> bool {
        (self.raw & (1 << 3)) != 0
    }

    /// Whether ultrasonic ground surface sonar is active (Bit 4).
    #[inline]
    pub const fn is_swave_work(&self) -> bool {
        (self.raw & (1 << 4)) != 0
    }

    /// Return-To-Home navigation status (Bits 5..=7).
    #[inline]
    pub const fn go_home_status(&self) -> GoHomeStatus {
        GoHomeStatus::from_bits((self.raw >> 5) & 0x07)
    }
}

/// OSD flight status flags bitmask wrapper (Bytes 32..36).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct OsdFlightStatus {
    /// Raw 32-bit little-endian status flags.
    pub raw: u32,
}

impl OsdFlightStatus {
    /// Creates a new `OsdFlightStatus` view from raw 32-bit integer.
    #[inline]
    pub const fn new(raw: u32) -> Self {
        Self { raw }
    }

    /// Flight controller navigation mode state machine (Bits 0..=6).
    #[inline]
    pub const fn flyc_state(&self) -> FlightMode {
        FlightMode::from_u8((self.raw & 0x7F) as u8)
    }

    /// Active-low failsafe alarm flag (Bit 7).
    ///
    /// **CRITICAL**: Return-To-Home failsafe is **ACTIVE when bit == 0** (`(flags & 0x80) == 0`).
    #[inline]
    pub const fn is_failsafe_active(&self) -> bool {
        (self.raw & (1 << 7)) == 0
    }

    /// Optical flow / vision positioning active in control loop (Bit 8).
    #[inline]
    pub const fn is_vision_used(&self) -> bool {
        (self.raw & (1 << 8)) != 0
    }

    /// GNSS lock unavailability diagnosis reason code (Bits 8..=11).
    #[inline]
    pub const fn gps_non_cause(&self) -> u8 {
        ((self.raw >> 8) & 0x0F) as u8
    }

    /// Battery voltage warning tier: 0=None, 1=Level 1, 2=Critical (Bits 9..=10).
    #[inline]
    pub const fn voltage_warning(&self) -> u8 {
        ((self.raw >> 9) & 0x03) as u8
    }

    /// Whether IMU thermal regulation stabilization is achieved (Bit 12).
    #[inline]
    pub const fn is_imu_preheated(&self) -> bool {
        (self.raw & (1 << 12)) != 0
    }

    /// RC hardware flight mode toggle switch position: 0=P, 1=S, 2=A (Bits 13..=14).
    #[inline]
    pub const fn mode_channel(&self) -> u8 {
        ((self.raw >> 13) & 0x03) as u8
    }

    /// RC hardware flight mode switch position as strongly-typed enum.
    #[inline]
    pub const fn mode_channel_enum(&self) -> ModeChannel {
        ModeChannel::from_bits(self.mode_channel())
    }

    /// GNSS satellites active in primary positioning filter (Bit 15).
    #[inline]
    pub const fn is_gps_used(&self) -> bool {
        (self.raw & (1 << 15)) != 0
    }

    /// Magnetic compass interference / anomaly detected (Bit 16).
    #[inline]
    pub const fn is_compass_error(&self) -> bool {
        (self.raw & (1 << 16)) != 0
    }

    /// Ultrasonic sonar transceiver failure (Bit 17).
    #[inline]
    pub const fn is_wave_error(&self) -> bool {
        (self.raw & (1 << 17)) != 0
    }

    /// GNSS signal quality rating indicator ($0 \dots 5$) (Bits 18..=21).
    #[inline]
    pub const fn gps_level(&self) -> u8 {
        ((self.raw >> 18) & 0x0F) as u8
    }

    /// Battery architecture classification: 0=Non-smart, 1=Smart, 2=Dual (Bits 22..=23).
    #[inline]
    pub const fn battery_type(&self) -> u8 {
        ((self.raw >> 22) & 0x03) as u8
    }

    /// Battery architecture classification as strongly-typed enum.
    #[inline]
    pub const fn battery_type_enum(&self) -> BatteryType {
        BatteryType::from_bits(self.battery_type())
    }

    /// Accelerometer saturation alert (Bit 24).
    #[inline]
    pub const fn is_accelerometer_over_range(&self) -> bool {
        (self.raw & (1 << 24)) != 0
    }

    /// Alias for accelerometer saturation alert.
    #[inline]
    pub const fn is_accelerator_over_range(&self) -> bool {
        self.is_accelerometer_over_range()
    }

    /// Excessive structural airframe vibration alert (Bit 25).
    #[inline]
    pub const fn is_vibrating(&self) -> bool {
        (self.raw & (1 << 25)) != 0
    }

    /// Barometric pressure sensor telemetry failure (Bit 26).
    #[inline]
    pub const fn is_barometer_dead_in_air(&self) -> bool {
        (self.raw & (1 << 26)) != 0
    }

    /// Motor thrust deficiency / excessive wind alert (Bit 27).
    #[inline]
    pub const fn is_not_enough_force(&self) -> bool {
        (self.raw & (1 << 27)) != 0
    }

    /// Motor rotor obstruction / stall detected (Bit 28).
    #[inline]
    pub const fn is_motor_blocked(&self) -> bool {
        (self.raw & (1 << 28)) != 0
    }

    /// Propeller detachment in flight detected (Bit 29).
    #[inline]
    pub const fn is_propeller_catapult(&self) -> bool {
        (self.raw & (1 << 29)) != 0
    }

    /// RTH cruising altitude was adjusted during flight (Bit 30).
    #[inline]
    pub const fn is_go_home_height_modified(&self) -> bool {
        (self.raw & (1 << 30)) != 0
    }

    /// Distance or ceiling geofence boundary encountered (Bit 31).
    #[inline]
    pub const fn is_out_of_limit(&self) -> bool {
        (self.raw & (1 << 31)) != 0
    }
}

/// Decoded OSD Telemetry Record (Record Type 1).
///
/// Encapsulates instantaneous aircraft 3D position, barometric altitude,
/// velocities in local NED frame, Euler attitude angles, flight modes, and health metrics.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct OsdRecord {
    /// WGS84 Geodetic Longitude in decimal degrees ($-180.0^\circ \dots +180.0^\circ$).
    pub longitude_deg: f64,
    /// WGS84 Geodetic Latitude in decimal degrees ($-90.0^\circ \dots +90.0^\circ$).
    pub latitude_deg: f64,
    /// Raw WGS84 Longitude in radians.
    pub longitude_rad: f64,
    /// Raw WGS84 Latitude in radians.
    pub latitude_rad: f64,
    /// Barometric altitude relative to takeoff surface elevation in meters.
    pub height_m: f64,
    /// Velocity along North axis in meters per second (NED frame, $+ = \text{North}$).
    pub x_speed_mps: f64,
    /// Velocity along East axis in meters per second (NED frame, $+ = \text{East}$).
    pub y_speed_mps: f64,
    /// Vertical descent velocity in meters per second (NED frame, $+ = \text{Down}$).
    pub z_speed_mps: f64,
    /// Aircraft pitch elevation angle in decimal degrees ($+ = \text{Nose Up}$).
    pub pitch_deg: f64,
    /// Aircraft roll banking angle in decimal degrees ($+ = \text{Right Wing Down}$).
    pub roll_deg: f64,
    /// Aircraft yaw azimuth angle in decimal degrees ($-180.0^\circ \dots +180.0^\circ$, $0^\circ = \text{True North}$).
    pub yaw_deg: f64,
    /// Flight status bitmask view (Byte 30).
    pub fly_state: OsdFlyState,
    /// Flight controller command dispatch state code (Byte 31).
    pub flyc_command: u8,
    /// Comprehensive flight controller status flags (Bytes 32..36).
    pub flight_status: OsdFlightStatus,
    /// Total locked GNSS satellites (GPS + GLONASS + BeiDou + Galileo) (Byte 36).
    pub gps_satellite_count: u8,
    /// High-level automated flight action code (Byte 37).
    pub flight_action: u8,
    /// Motor arming status and ESC communication health bitmask (Bytes 38..40).
    pub motor_status: u16,
    /// Battery State of Charge percentage ($0 \dots 100\%$) (Byte 40).
    pub battery_percentage: u8,
    /// Ultrasonic / radar ground clearance in meters (Byte 41).
    pub wave_height_m: f64,
    /// Cumulative motor running sortie duration in seconds (Bytes 42..44).
    pub fly_time_s: f64,
    /// Lifetime aircraft motor start counter (Bytes 44..46).
    pub startup_times: u16,
    /// Flight controller firmware revision code (Byte 47).
    pub flyc_version: u8,
    /// Aircraft drone model identifier (Byte 48).
    pub drone_type: u8,
    /// IMU initialization failure reason code (Byte 49).
    pub imu_init_fail_reason: u8,
    /// Motor failure reason code (Byte 50).
    pub motor_failed_reason: u8,
    /// SDK control authority device identifier (Byte 52).
    pub sdk_control_device: u8,
}

impl OsdRecord {
    /// Parses an OSD telemetry payload from a borrowed byte slice.
    ///
    /// # Errors
    /// Returns [`FlightReaderError::MalformedPayload`] if `payload.len() < 53`.
    pub fn parse(payload: &[u8]) -> Result<Self> {
        if payload.len() < MIN_OSD_PAYLOAD_LEN {
            return Err(FlightReaderError::MalformedPayload {
                record_type: RECORD_TYPE,
                reason: "OSD payload shorter than 53 bytes",
            });
        }

        let lon_rad = LittleEndian::read_f64(&payload[0..8]);
        let lat_rad = LittleEndian::read_f64(&payload[8..16]);
        let height_raw = LittleEndian::read_i16(&payload[16..18]);
        let x_speed_raw = LittleEndian::read_i16(&payload[18..20]);
        let y_speed_raw = LittleEndian::read_i16(&payload[20..22]);
        let z_speed_raw = LittleEndian::read_i16(&payload[22..24]);
        let pitch_raw = LittleEndian::read_i16(&payload[24..26]);
        let roll_raw = LittleEndian::read_i16(&payload[26..28]);
        let yaw_raw = LittleEndian::read_i16(&payload[28..30]);
        let fly_state_raw = payload[30];
        let flyc_command = payload[31];
        let flight_status_raw = LittleEndian::read_u32(&payload[32..36]);
        let gps_satellite_count = payload[36];
        let flight_action = payload[37];
        let motor_status = LittleEndian::read_u16(&payload[38..40]);
        let battery_percentage = payload[40];
        let wave_height_raw = payload[41];
        let fly_time_raw = LittleEndian::read_u16(&payload[42..44]);
        let startup_times = LittleEndian::read_u16(&payload[44..46]);
        let flyc_version = payload[47];
        let drone_type = payload[48];
        let imu_init_fail_reason = payload[49];
        let motor_failed_reason = payload[50];
        let sdk_control_device = payload[52];

        Ok(Self {
            longitude_deg: lon_rad * RAD_TO_DEG,
            latitude_deg: lat_rad * RAD_TO_DEG,
            longitude_rad: lon_rad,
            latitude_rad: lat_rad,
            height_m: height_raw as f64 / 10.0,
            x_speed_mps: x_speed_raw as f64 / 10.0,
            y_speed_mps: y_speed_raw as f64 / 10.0,
            z_speed_mps: z_speed_raw as f64 / 10.0,
            pitch_deg: pitch_raw as f64 / 10.0,
            roll_deg: roll_raw as f64 / 10.0,
            yaw_deg: yaw_raw as f64 / 10.0,
            fly_state: OsdFlyState::new(fly_state_raw),
            flyc_command,
            flight_status: OsdFlightStatus::new(flight_status_raw),
            gps_satellite_count,
            flight_action,
            motor_status,
            battery_percentage,
            wave_height_m: wave_height_raw as f64 / 10.0,
            fly_time_s: fly_time_raw as f64 / 10.0,
            startup_times,
            flyc_version,
            drone_type,
            imu_init_fail_reason,
            motor_failed_reason,
            sdk_control_device,
        })
    }

    /// Horizontal ground speed: $V_h = \sqrt{v_x^2 + v_y^2}$ in m/s.
    #[inline]
    pub fn horizontal_speed(&self) -> f64 {
        self.x_speed_mps.hypot(self.y_speed_mps)
    }

    /// 3D flight speed: $V_{3D} = \sqrt{v_x^2 + v_y^2 + v_z^2}$ in m/s.
    #[inline]
    pub fn speed_3d(&self) -> f64 {
        self.horizontal_speed().hypot(self.z_speed_mps)
    }

    /// Vertical climb velocity in m/s (positive upward, $-v_z$).
    #[inline]
    pub fn vertical_climb_rate(&self) -> f64 {
        -self.z_speed_mps
    }

    /// Vertical climb rate alias.
    #[inline]
    pub fn climb_rate(&self) -> f64 {
        self.vertical_climb_rate()
    }

    /// Relative barometric altitude alias.
    #[inline]
    pub fn relative_height(&self) -> f64 {
        self.height_m
    }

    /// Barometric altitude alias.
    #[inline]
    pub fn barometric_altitude(&self) -> f64 {
        self.height_m
    }

    /// Compass heading normalized to the interval $[0.0^\circ, 360.0^\circ)$.
    #[inline]
    pub fn yaw_360(&self) -> f64 {
        let norm = (self.yaw_deg + 360.0) % 360.0;
        if norm < 0.0 {
            norm + 360.0
        } else {
            norm
        }
    }

    /// Latitude encoded as signed 32-bit integer multiplied by $10^7$.
    #[inline]
    pub fn latitude_1e7(&self) -> i32 {
        (self.latitude_deg * 10_000_000.0).round() as i32
    }

    /// Longitude encoded as signed 32-bit integer multiplied by $10^7$.
    #[inline]
    pub fn longitude_1e7(&self) -> i32 {
        (self.longitude_deg * 10_000_000.0).round() as i32
    }

    /// Validates whether geodetic coordinates represent a valid non-zero location.
    #[inline]
    pub fn is_valid_coordinates(&self) -> bool {
        self.latitude_deg >= -90.0
            && self.latitude_deg <= 90.0
            && self.longitude_deg >= -180.0
            && self.longitude_deg <= 180.0
            && (self.latitude_deg != 0.0 || self.longitude_deg != 0.0)
            && !self.latitude_deg.is_nan()
            && !self.longitude_deg.is_nan()
    }

    /// Automated flight action as strongly-typed enum.
    #[inline]
    pub fn flight_action_enum(&self) -> FlightAction {
        FlightAction::from_u8(self.flight_action)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_osd_parse_authoritative_synthetic_vector() {
        let hex_bytes: [u8; 55] = [
            0x91, 0xE9, 0xA8, 0x33, 0xCD, 0x17, 0x01, 0xC0, // lon
            0x96, 0xCD, 0x55, 0xC8, 0xF5, 0x18, 0xE5, 0x3F, // lat
            0xE6, 0x04, // height: 1254 -> 125.4 m
            0x55, 0x00, // x_speed: 85 -> 8.5 m/s
            0xD6, 0xFF, // y_speed: -42 -> -4.2 m/s
            0x12, 0x00, // z_speed: 18 -> 1.8 m/s
            0x7B, 0x00, // pitch: 123 -> 12.3 deg
            0xC7, 0xFF, // roll: -57 -> -5.7 deg
            0xB2, 0x05, // yaw: 1458 -> 145.8 deg
            0x7B, // fly_state: 0x7B
            0x05, // flyc_command: 5
            0x0C, 0xA0, 0x42, 0x00, // flight_status: 0x0042A00C
            0x12, // gps_satellite_count: 18
            0x00, // flight_action: 0
            0x00, 0x00, // motor_status: 0
            0x55, // battery_percentage: 85%
            0x00, // wave_height: 0.0 m
            0x29, 0x09, // fly_time: 2345 -> 234.5 s
            0x00, 0x00, // startup_times: 0
            0x00, // reserved
            0x00, // flyc_version: 0
            0x00, // drone_type: 0
            0x00, // imu_init_fail: 0
            0x00, // motor_failed: 0
            0x00, // reserved
            0x00, // sdk_control: 0
        ];

        let osd = OsdRecord::parse(&hex_bytes).expect("Must parse valid 55-byte OSD record");
        assert!((osd.longitude_deg - (-122.419415)).abs() < 1e-5);
        assert!((osd.latitude_deg - 37.774929).abs() < 1e-5);
        assert!((osd.height_m - 125.4).abs() < 1e-2);
        assert!((osd.x_speed_mps - 8.5).abs() < 1e-2);
        assert!((osd.y_speed_mps - (-4.2)).abs() < 1e-2);
        assert!((osd.z_speed_mps - 1.8).abs() < 1e-2);
        assert!((osd.horizontal_speed() - 9.48103).abs() < 1e-4);
        assert!((osd.speed_3d() - 9.65039).abs() < 1e-4);
        assert!((osd.vertical_climb_rate() - (-1.8)).abs() < 1e-2);
        assert!((osd.climb_rate() - (-1.8)).abs() < 1e-2);
        assert!((osd.pitch_deg - 12.3).abs() < 1e-2);
        assert!((osd.roll_deg - (-5.7)).abs() < 1e-2);
        assert!((osd.yaw_deg - 145.8).abs() < 1e-2);
        assert!((osd.yaw_360() - 145.8).abs() < 1e-2);

        // Byte 30 bitmask checks
        assert!(osd.fly_state.can_ioc_work());
        assert_eq!(osd.fly_state.ground_state(), GroundState::OnGround);
        assert!(osd.fly_state.is_motor_up());
        assert!(osd.fly_state.is_swave_work());
        assert_eq!(osd.fly_state.go_home_status(), GoHomeStatus::Cruising);

        // Bytes 32..36 status checks
        assert_eq!(osd.flight_status.flyc_state(), FlightMode::AutoLanding);
        assert!(osd.flight_status.is_failsafe_active()); // ACTIVE: bit 7 == 0
        assert_eq!(osd.flight_status.mode_channel(), 1); // S-mode
        assert_eq!(osd.flight_status.mode_channel_enum(), ModeChannel::Sport);
        assert!(osd.flight_status.is_gps_used());
        assert_eq!(osd.flight_status.gps_level(), 4);
        assert_eq!(osd.flight_status.battery_type(), 1);
        assert_eq!(osd.flight_status.battery_type_enum(), BatteryType::Smart);

        // Metrics
        assert_eq!(osd.gps_satellite_count, 18);
        assert_eq!(osd.battery_percentage, 85);
        assert!((osd.fly_time_s - 234.5).abs() < 1e-2);
        assert!(osd.is_valid_coordinates());
        assert_eq!(osd.latitude_1e7(), 377749290);
        assert_eq!(osd.longitude_1e7(), -1224194150);
    }

    #[test]
    fn test_osd_active_low_failsafe_invariant() {
        let mut payload = vec![0u8; 53];

        // Case 1: Bit 7 == 0 -> Failsafe MUST BE TRUE (Active)
        LittleEndian::write_u32(&mut payload[32..36], 0x0000_0000);
        let osd1 = OsdRecord::parse(&payload).unwrap();
        assert!(osd1.flight_status.is_failsafe_active());

        // Case 2: Bit 7 == 1 -> Failsafe MUST BE FALSE (Inactive)
        LittleEndian::write_u32(&mut payload[32..36], 0x0000_0080);
        let osd2 = OsdRecord::parse(&payload).unwrap();
        assert!(!osd2.flight_status.is_failsafe_active());
    }

    #[test]
    fn test_osd_truncated_rejection() {
        let payload = [0u8; 52];
        let err = OsdRecord::parse(&payload).unwrap_err();
        assert_eq!(
            err,
            FlightReaderError::MalformedPayload {
                record_type: 1,
                reason: "OSD payload shorter than 53 bytes",
            }
        );
    }
}

//! Home Point & Takeoff Telemetry Decoder (Record Type 2).
//!
//! Decodes calibrated home coordinates, RTH cruise altitude,
//! failsafe flags, and the critical `HomeDataRecorderFileIndex` linking pointer.

use byteorder::{ByteOrder, LittleEndian};

use crate::error::{FlightReaderError, Result};

/// Telemetry record type identifier for Home Point packets.
pub const RECORD_TYPE: u8 = 2;

/// Minimum payload length in bytes for Home Point telemetry records.
pub const MIN_HOME_PAYLOAD_LEN: usize = 46;

/// Multiplicative conversion factor from radians to decimal degrees ($180.0 / \pi$).
pub const RAD_TO_DEG: f64 = 180.0 / std::f64::consts::PI;

/// Home point status flags view (Bytes 20..22).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct HomeStatusFlags {
    /// Raw 16-bit status integer.
    pub raw: u16,
}

impl HomeStatusFlags {
    /// Creates a new `HomeStatusFlags` view from raw 16-bit integer.
    #[inline]
    pub const fn new(raw: u16) -> Self {
        Self { raw }
    }

    /// Whether Home Point is recorded and valid (Bit 0).
    #[inline]
    pub const fn is_home_record(&self) -> bool {
        (self.raw & 0x01) != 0
    }

    /// Return-To-Home mode: 0=Standard, 1=Dynamic follow home point (Bit 1).
    #[inline]
    pub const fn go_home_mode(&self) -> u8 {
        ((self.raw >> 1) & 0x01) as u8
    }

    /// Course lock reference heading mode (Bit 2).
    #[inline]
    pub const fn aircraft_head_direction(&self) -> u8 {
        ((self.raw >> 2) & 0x01) as u8
    }

    /// Dynamic Home Point updates enabled from mobile device / RC GPS (Bit 3).
    #[inline]
    pub const fn is_dynamic_home_point_enabled(&self) -> bool {
        (self.raw & (1 << 3)) != 0
    }

    /// Drone has reached configured maximum distance geofence (Bit 4).
    #[inline]
    pub const fn is_reach_limit_distance(&self) -> bool {
        (self.raw & (1 << 4)) != 0
    }

    /// Drone has reached configured maximum altitude ceiling (Bit 5).
    #[inline]
    pub const fn is_reach_limit_height(&self) -> bool {
        (self.raw & (1 << 5)) != 0
    }

    /// Multiple flight modes (P/S/A) toggle switch enabled in app settings (Bit 6).
    #[inline]
    pub const fn is_multiple_flight_mode_enabled(&self) -> bool {
        (self.raw & (1 << 6)) != 0
    }

    /// Compass ceiling limitation status code ($0 \dots 3$) (Bits 8..=9).
    #[inline]
    pub const fn compass_ceiling_status(&self) -> u8 {
        ((self.raw >> 8) & 0x03) as u8
    }

    /// Compass ceiling altitude cap actively enforced (Bit 10).
    #[inline]
    pub const fn is_compass_ceiling(&self) -> bool {
        (self.raw & (1 << 10)) != 0
    }

    /// Beginner mode active ($30\text{m}$ ceiling/radius constraint) (Bit 11).
    #[inline]
    pub const fn is_beginner_mode(&self) -> bool {
        (self.raw & (1 << 11)) != 0
    }

    /// Intelligent Orientation Control (IOC) enabled (Bit 12).
    #[inline]
    pub const fn is_ioc(&self) -> bool {
        (self.raw & (1 << 12)) != 0
    }

    /// IOC mode: 0=None, 1=CourseLock, 2=HomeLock, 3=HotspotSurround (Bits 13..=15).
    #[inline]
    pub const fn ioc_mode(&self) -> u8 {
        ((self.raw >> 13) & 0x07) as u8
    }
}

/// Decoded Home Point telemetry record (Record Type 2).
///
/// Encapsulates calibrated takeoff coordinates, ground reference elevation,
/// Return-To-Home cruise altitude, status flags, and the critical
/// `HomeDataRecorderFileIndex` linking pointer.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct HomeRecord {
    /// WGS84 Home Point Longitude in decimal degrees ($-180.0^\circ \dots +180.0^\circ$).
    pub longitude_deg: f64,
    /// WGS84 Home Point Latitude in decimal degrees ($-90.0^\circ \dots +90.0^\circ$).
    pub latitude_deg: f64,
    /// Raw WGS84 Home Point Longitude in radians.
    pub longitude_rad: f64,
    /// Raw WGS84 Home Point Latitude in radians.
    pub latitude_rad: f64,
    /// Ground reference barometric altitude at Home Point in meters.
    pub height_m: f32,
    /// Status and calibration flags (Bytes 20..22).
    pub status: HomeStatusFlags,
    /// Configured Return-To-Home cruise failsafe altitude in meters.
    pub go_home_height_m: u16,
    /// Reference heading angle for Course Lock flight mode in decimal degrees.
    pub course_lock_angle_deg: f64,
    /// On-board hardware blackbox recording sequence index (`FLY{index:03}.DAT`).
    pub data_recorder_file_index: u16,
    /// Critical battery auto forced-landing descent altitude in meters.
    pub force_landing_height_m: u8,
}

impl HomeRecord {
    /// Parses a Home Point telemetry payload from a borrowed byte slice.
    ///
    /// # Errors
    /// Returns [`FlightReaderError::MalformedPayload`] if `payload.len() < 46`.
    pub fn parse(payload: &[u8]) -> Result<Self> {
        if payload.len() < MIN_HOME_PAYLOAD_LEN {
            return Err(FlightReaderError::MalformedPayload {
                record_type: RECORD_TYPE,
                reason: "Home payload shorter than 46 bytes",
            });
        }

        let lon_rad = LittleEndian::read_f64(&payload[0..8]);
        let lat_rad = LittleEndian::read_f64(&payload[8..16]);
        let height_raw = LittleEndian::read_f32(&payload[16..20]);
        let status_raw = LittleEndian::read_u16(&payload[20..22]);
        let go_home_height_m = LittleEndian::read_u16(&payload[22..24]);
        let course_lock_raw = LittleEndian::read_i16(&payload[24..26]);
        let data_recorder_file_index = LittleEndian::read_u16(&payload[30..32]);
        let force_landing_height_m = payload[45];

        Ok(Self {
            longitude_deg: lon_rad * RAD_TO_DEG,
            latitude_deg: lat_rad * RAD_TO_DEG,
            longitude_rad: lon_rad,
            latitude_rad: lat_rad,
            height_m: height_raw / 10.0,
            status: HomeStatusFlags::new(status_raw),
            go_home_height_m,
            course_lock_angle_deg: course_lock_raw as f64 / 10.0,
            data_recorder_file_index,
            force_landing_height_m,
        })
    }

    /// Returns correlated on-board blackbox filename (e.g. `FLY142.DAT`), or `None` if index is 0.
    pub fn dat_file_name(&self) -> Option<String> {
        if self.data_recorder_file_index > 0 {
            Some(format!("FLY{:03}.DAT", self.data_recorder_file_index))
        } else {
            None
        }
    }

    /// Latitude encoded as signed 32-bit integer multiplied by $10^7$.
    #[inline]
    pub fn latitude_1e7(&self) -> i32 {
        (self.latitude_deg * 10_000_000.0).round() as i32
    }

    /// Longitude encoded as signed 32-bit integer multiplied by $10^7$.
    #[inline]
    pub fn longitude_1e7(&self) -> i32 {
        (self.longitude_deg * 10_000_000.0).round() as i32
    }

    /// Validates whether geodetic coordinates represent a valid non-zero location.
    #[inline]
    pub fn is_valid_coordinates(&self) -> bool {
        self.latitude_deg >= -90.0
            && self.latitude_deg <= 90.0
            && self.longitude_deg >= -180.0
            && self.longitude_deg <= 180.0
            && (self.latitude_deg != 0.0 || self.longitude_deg != 0.0)
            && !self.latitude_deg.is_nan()
            && !self.longitude_deg.is_nan()
    }
}

