//! DJI `.txt` Gimbal Telemetry Decoder (Record Type 3).
//!
//! Decodes 3-axis gimbal orientation (pitch, roll, yaw), mechanical/software limit
//! bitmasks, motor stall detection, stabilization modes, and horizon-relative tilt.

use byteorder::{ByteOrder, LittleEndian};

use crate::error::{FlightReaderError, Result};

/// Telemetry record type identifier for Gimbal packets.
pub const RECORD_TYPE: u8 = 3;

/// Minimum allowable payload length (bytes 0..6: pitch, roll, yaw, bitmask).
pub const MIN_PAYLOAD_LEN: usize = 7;

/// Extended payload length including horizon-relative tilt (bytes 20..21).
pub const EXTENDED_PAYLOAD_LEN: usize = 22;

/// Gimbal stabilization and tracking operational mode.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum GimbalMode {
    /// Gimbal orientation is uncoupled from aircraft yaw.
    Free = 0,
    /// Gimbal yaw follows aircraft heading, roll follows RC roll channel (First-Person View).
    Fpv = 1,
    /// Gimbal yaw smoothly follows aircraft nose heading ("Follow Yaw").
    Follow = 2,
    /// Unmapped or vendor-reserved mode code.
    Unknown(u8),
}

impl GimbalMode {
    /// Creates a `GimbalMode` from raw 2-bit value (0..=3).
    #[inline]
    pub const fn from_bits(bits: u8) -> Self {
        match bits & 0x03 {
            0 => Self::Free,
            1 => Self::Fpv,
            2 => Self::Follow,
            other => Self::Unknown(other),
        }
    }

    /// Returns the descriptive display label matching C# `ClsLog.GimbalModeText`.
    #[inline]
    pub const fn as_str(&self) -> &'static str {
        match self {
            Self::Free => "Free",
            Self::Fpv => "FPV",
            Self::Follow => "Follow Yaw",
            Self::Unknown(_) => "Unknown",
        }
    }
}

/// Decoded Gimbal Telemetry Record (Record Type 3).
#[derive(Debug, Clone, PartialEq)]
pub struct GimbalRecord {
    /// Raw signed pitch angle (deci-degrees, $\times 10$).
    pub raw_pitch: i16,
    /// Raw signed roll angle (deci-degrees, $\times 10$).
    pub raw_roll: i16,
    /// Raw signed yaw angle (deci-degrees, $\times 10$).
    pub raw_yaw: i16,
    /// Raw status and limit bitmask byte.
    pub raw_bitmask: u8,
    /// Raw signed tilt angle relative to horizon (deci-degrees, $\times 10$), if available.
    pub raw_tilt: Option<i16>,

    /// Gimbal pitch angle in decimal degrees ($-90.0^\circ \dots +30.0^\circ$).
    /// Positive values tilt upward; negative values tilt downward toward nadir.
    pub pitch_deg: f64,
    /// Gimbal roll leveling angle in decimal degrees.
    pub roll_deg: f64,
    /// Gimbal yaw azimuth angle in decimal degrees ($-180.0^\circ \dots +180.0^\circ$ relative to nose).
    pub yaw_deg: f64,
    /// Absolute gimbal tilt angle relative to horizon in decimal degrees, if present.
    pub tilt_deg: Option<f64>,

    /// Whether the pitch axis has reached its physical or configured limit (Bit 0).
    pub is_at_pitch_limit: bool,
    /// Whether the roll axis has reached its physical or configured limit (Bit 1).
    pub is_at_roll_limit: bool,
    /// Whether the yaw axis has reached its physical or configured limit (Bit 2).
    pub is_at_yaw_limit: bool,
    /// Whether gimbal motor stall or physical obstruction is detected (Bit 6).
    pub is_stuck: bool,
    /// Gimbal stabilization operational mode (Bits 6..=7).
    pub mode: GimbalMode,
}

impl GimbalRecord {
    /// Parses a Gimbal telemetry record from a borrowed payload slice.
    ///
    /// # Errors
    /// Returns [`FlightReaderError::TruncatedRecord`] if `payload.len() < 7`.
    pub fn parse(payload: &[u8]) -> Result<Self> {
        if payload.len() < MIN_PAYLOAD_LEN {
            return Err(FlightReaderError::TruncatedRecord {
                expected: MIN_PAYLOAD_LEN,
                available: payload.len(),
            });
        }

        let raw_pitch = LittleEndian::read_i16(&payload[0..2]);
        let raw_roll = LittleEndian::read_i16(&payload[2..4]);
        let raw_yaw = LittleEndian::read_i16(&payload[4..6]);
        let raw_bitmask = payload[6];

        let (raw_tilt, tilt_deg) = if payload.len() >= EXTENDED_PAYLOAD_LEN {
            let t = LittleEndian::read_i16(&payload[20..22]);
            (Some(t), Some(t as f64 / 10.0))
        } else {
            (None, None)
        };

        let pitch_deg = raw_pitch as f64 / 10.0;
        let roll_deg = raw_roll as f64 / 10.0;
        let yaw_deg = raw_yaw as f64 / 10.0;

        let is_at_pitch_limit = (raw_bitmask & 0x01) != 0;
        let is_at_roll_limit = (raw_bitmask & 0x02) != 0;
        let is_at_yaw_limit = (raw_bitmask & 0x04) != 0;
        let is_stuck = (raw_bitmask & 0x40) != 0;
        let mode = GimbalMode::from_bits((raw_bitmask >> 6) & 0x03);

        Ok(Self {
            raw_pitch,
            raw_roll,
            raw_yaw,
            raw_bitmask,
            raw_tilt,
            pitch_deg,
            roll_deg,
            yaw_deg,
            tilt_deg,
            is_at_pitch_limit,
            is_at_roll_limit,
            is_at_yaw_limit,
            is_stuck,
            mode,
        })
    }

    /// Normalizes yaw azimuth to the standard compass interval $[0.0^\circ, 360.0^\circ)$.
    #[inline]
    pub fn yaw_360(&self) -> f64 {
        if self.yaw_deg < 0.0 {
            self.yaw_deg + 360.0
        } else {
            self.yaw_deg
        }
    }

    /// Returns `true` if any mechanical or configured axis limit is hit.
    #[inline]
    pub const fn is_at_any_limit(&self) -> bool {
        self.is_at_pitch_limit || self.is_at_roll_limit || self.is_at_yaw_limit
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_gimbal_neutral_free_mode() {
        // Pitch: 0, Roll: 0, Yaw: 0, Bitmask: 0x00 (Free mode, no limits, not stuck)
        let payload = [0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00];
        let record = GimbalRecord::parse(&payload).expect("Must parse 7-byte neutral record");
        assert_eq!(record.raw_pitch, 0);
        assert_eq!(record.raw_roll, 0);
        assert_eq!(record.raw_yaw, 0);
        assert_eq!(record.pitch_deg, 0.0);
        assert_eq!(record.roll_deg, 0.0);
        assert_eq!(record.yaw_deg, 0.0);
        assert_eq!(record.yaw_360(), 0.0);
        assert_eq!(record.mode, GimbalMode::Free);
        assert!(!record.is_stuck);
        assert!(!record.is_at_any_limit());
        assert_eq!(record.tilt_deg, None);
    }

    #[test]
    fn test_gimbal_limits_and_stuck_fpv_mode() {
        // Pitch: -90.0° (-900 = 0xFC7C -> [0x7C, 0xFC])
        // Roll: +30.0° (300 = 0x012C -> [0x2C, 0x01])
        // Yaw: -175.5° (-1755 = 0xF925 -> [0x25, 0xF9])
        // Bitmask: 0x47 (Bit 0: PitchLim, Bit 1: RollLim, Bit 2: YawLim, Bit 6: Stuck, Bits 6-7: 01 = FPV)
        let payload = [0x7C, 0xFC, 0x2C, 0x01, 0x25, 0xF9, 0x47];
        let record = GimbalRecord::parse(&payload).expect("Must parse limits record");
        assert_eq!(record.raw_pitch, -900);
        assert_eq!(record.raw_roll, 300);
        assert_eq!(record.raw_yaw, -1755);
        assert!((record.pitch_deg - (-90.0)).abs() < 1e-9);
        assert!((record.roll_deg - 30.0).abs() < 1e-9);
        assert!((record.yaw_deg - (-175.5)).abs() < 1e-9);
        assert!((record.yaw_360() - 184.5).abs() < 1e-9);
        assert!(record.is_at_pitch_limit);
        assert!(record.is_at_roll_limit);
        assert!(record.is_at_yaw_limit);
        assert!(record.is_at_any_limit());
        assert!(record.is_stuck);
        assert_eq!(record.mode, GimbalMode::Fpv);
        assert_eq!(record.mode.as_str(), "FPV");
    }

    #[test]
    fn test_gimbal_extended_22_byte_tilt_follow_yaw() {
        let mut payload = vec![0u8; 22];
        payload[0..2].copy_from_slice(&152i16.to_le_bytes());
        payload[2..4].copy_from_slice(&(-15i16).to_le_bytes());
        payload[4..6].copy_from_slice(&1200i16.to_le_bytes());
        payload[6] = 0x80;
        payload[20..22].copy_from_slice(&(-450i16).to_le_bytes());

        let record = GimbalRecord::parse(&payload).expect("Must parse 22-byte extended record");
        assert!((record.pitch_deg - 15.2).abs() < 1e-9);
        assert!((record.roll_deg - (-1.5)).abs() < 1e-9);
        assert!((record.yaw_deg - 120.0).abs() < 1e-9);
        assert_eq!(record.mode, GimbalMode::Follow);
        assert_eq!(record.mode.as_str(), "Follow Yaw");
        assert!(!record.is_stuck);
        assert_eq!(record.raw_tilt, Some(-450));
        assert!((record.tilt_deg.unwrap() - (-45.0)).abs() < 1e-9);
    }

    #[test]
    fn test_gimbal_truncated_rejection() {
        let payload = [0x00u8; 6];
        let err = GimbalRecord::parse(&payload).unwrap_err();
        match err {
            FlightReaderError::TruncatedRecord {
                expected,
                available,
            } => {
                assert_eq!(expected, 7);
                assert_eq!(available, 6);
            }
            other => panic!("Unexpected error: {:?}", other),
        }
    }
}

//! DJI `.txt` Remote Controller Telemetry Decoder (Record Type 4).
//!
//! Decodes 4 physical control stick axes (Aileron, Elevator, Throttle, Rudder),
//! gimbal pitch dial (Gyro), flight mode switches, wheel scroll, and button bitmasks.

use byteorder::{ByteOrder, LittleEndian};

use crate::error::{FlightReaderError, Result};

/// Telemetry record type identifier for Remote Controller packets.
pub const RECORD_TYPE: u8 = 4;

/// Minimum allowable payload length (bytes 0..9: sticks + gyro).
pub const MIN_PAYLOAD_LEN: usize = 10;

/// Standard payload length including 32-bit button/switch bitmask.
pub const STANDARD_PAYLOAD_LEN: usize = 14;

/// Calibrated stick center / neutral value.
pub const STICK_CENTER: i16 = 1024;

/// Calibrated stick minimum travel boundary.
pub const STICK_MIN: i16 = 364;

/// Calibrated stick maximum travel boundary.
pub const STICK_MAX: i16 = 1684;

/// Calibrated half-span range $(1684 - 1024 = 660.0)$.
pub const STICK_HALF_RANGE: f64 = 660.0;

/// Normalizes a raw 16-bit stick channel into a floating point value in `[-1.0, +1.0]`.
///
/// Disconnected / uninitialized channels (`raw == 0`) map to neutral center `1024` (`0.0`).
/// Values beyond `[364, 1684]` are linearly extrapolated beyond `[-1.0, +1.0]`.
#[inline]
pub fn normalize_stick(raw: i16) -> f64 {
    let effective = if raw == 0 {
        STICK_CENTER as f64
    } else {
        raw as f64
    };
    (effective - STICK_CENTER as f64) / STICK_HALF_RANGE
}

/// Clamps the normalized stick value to the valid operational range `[-1.0, +1.0]`.
#[inline]
pub fn normalize_stick_clamped(raw: i16) -> f64 {
    normalize_stick(raw).clamp(-1.0, 1.0)
}

/// Converts a raw 16-bit stick value into an integer percentage in `[-100, +100]`.
#[inline]
pub fn stick_percent(raw: i16) -> i8 {
    let norm = normalize_stick(raw);
    (norm * 100.0).round() as i8
}

/// Returns whether the stick channel is at or beyond physical endpoint saturation.
#[inline]
pub fn is_stick_saturated(raw: i16) -> bool {
    raw != 0 && (raw <= STICK_MIN || raw >= STICK_MAX)
}

/// Remote controller flight mode toggle switch position.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum RcSwitchMode {
    /// Switch Position 0 (typically P-mode / Position).
    Position0 = 0,
    /// Switch Position 1 (typically S-mode / Sport).
    Position1 = 1,
    /// Switch Position 2 (typically A-mode / Atti or Cine).
    Position2 = 2,
    /// Switch Position 3 (Reserved / Multi-function).
    Position3 = 3,
}

impl RcSwitchMode {
    /// Constructs `RcSwitchMode` from raw 2-bit value.
    #[inline]
    pub const fn from_bits(bits: u8) -> Self {
        match bits & 0x03 {
            0 => Self::Position0,
            1 => Self::Position1,
            2 => Self::Position2,
            _ => Self::Position3,
        }
    }

    /// Returns the standard display text.
    #[inline]
    pub const fn as_str(&self) -> &'static str {
        match self {
            Self::Position0 => "0",
            Self::Position1 => "1",
            Self::Position2 => "2",
            Self::Position3 => "3",
        }
    }
}

/// Decoded Remote Controller Telemetry Record (Record Type 4).
#[derive(Debug, Clone, PartialEq)]
pub struct RcRecord {
    /// Raw Right Stick Horizontal channel (Aileron / Roll command).
    pub raw_aileron: i16,
    /// Raw Right Stick Vertical channel (Elevator / Pitch command).
    pub raw_elevator: i16,
    /// Raw Left Stick Vertical channel (Throttle / Climb command).
    pub raw_throttle: i16,
    /// Raw Left Stick Horizontal channel (Rudder / Yaw command).
    pub raw_rudder: i16,
    /// Raw Gimbal pitch control thumbwheel (Gyro channel).
    pub raw_gyro: i16,
    /// Raw 32-bit hardware button and switch bitmask.
    pub raw_button_bitmask: u32,

    /// Normalized Aileron input in `[-1.0, +1.0]` (Positive = Roll Right).
    pub aileron: f64,
    /// Normalized Elevator input in `[-1.0, +1.0]` (Positive = Pitch Forward).
    pub elevator: f64,
    /// Normalized Throttle input in `[-1.0, +1.0]` (Positive = Ascend).
    pub throttle: f64,
    /// Normalized Rudder input in `[-1.0, +1.0]` (Positive = Turn Right).
    pub rudder: f64,
    /// Normalized Gimbal thumbwheel input in `[-1.0, +1.0]`.
    pub gyro: f64,

    /// Whether the gimbal thumbwheel is pushed inward as a button (Bit 0).
    pub wheel_depressed: bool,
    /// Gimbal thumbwheel rotational offset / delta step (Bits 1..=5, $0 \dots 31$).
    pub wheel_offset: u8,
    /// Radio link signal quality / RSSI percentage (Bits 0..=6, $0 \dots 100\%$).
    pub signal_quality: u8,
    /// Whether Return-To-Home (RTH) physical button is held depressed (Bit 11).
    pub go_home_depressed: bool,
    /// Flight mode toggle switch raw position (Bits 12..=13, $0 \dots 3$).
    pub mode_raw: u8,
    /// Flight mode switch position enum.
    pub mode_switch: RcSwitchMode,
    /// Customizable button C4 pressed state (Bit 17).
    pub custom4_depressed: bool,
    /// Customizable button C3 pressed state (Bit 18).
    pub custom3_depressed: bool,
    /// Customizable button C2 pressed state (Bit 19).
    pub custom2_depressed: bool,
    /// Customizable button C1 pressed state (Bit 20).
    pub custom1_depressed: bool,
    /// Photo gallery / Playback button pressed state (Bit 21).
    pub playback_depressed: bool,
    /// Camera still photo shutter button pressed state (Bit 22).
    pub shutter_depressed: bool,
    /// Camera video record start/stop toggle button pressed state (Bit 23).
    pub record_depressed: bool,
}

impl RcRecord {
    /// Parses an RC telemetry record from a borrowed payload slice.
    ///
    /// # Errors
    /// Returns [`FlightReaderError::TruncatedRecord`] if `payload.len() < 10`.
    pub fn parse(payload: &[u8]) -> Result<Self> {
        if payload.len() < MIN_PAYLOAD_LEN {
            return Err(FlightReaderError::TruncatedRecord {
                expected: MIN_PAYLOAD_LEN,
                available: payload.len(),
            });
        }

        let raw_aileron = LittleEndian::read_i16(&payload[0..2]);
        let raw_elevator = LittleEndian::read_i16(&payload[2..4]);
        let raw_throttle = LittleEndian::read_i16(&payload[4..6]);
        let raw_rudder = LittleEndian::read_i16(&payload[6..8]);
        let raw_gyro = LittleEndian::read_i16(&payload[8..10]);

        // Resilient variable-length bitmask extraction (10 to 14+ bytes)
        let raw_button_bitmask = if payload.len() >= 14 {
            LittleEndian::read_u32(&payload[10..14])
        } else if payload.len() == 13 {
            (payload[10] as u32) | ((payload[11] as u32) << 8) | ((payload[12] as u32) << 16)
        } else if payload.len() == 12 {
            (payload[10] as u32) | ((payload[11] as u32) << 8)
        } else if payload.len() == 11 {
            payload[10] as u32
        } else {
            0u32
        };

        let aileron = normalize_stick(raw_aileron);
        let elevator = normalize_stick(raw_elevator);
        let throttle = normalize_stick(raw_throttle);
        let rudder = normalize_stick(raw_rudder);
        let gyro = normalize_stick(raw_gyro);

        let wheel_depressed = (raw_button_bitmask & 0x01) != 0;
        let wheel_offset = ((raw_button_bitmask >> 1) & 0x1F) as u8;
        let signal_quality = (raw_button_bitmask & 0x7F) as u8;
        let go_home_depressed = (raw_button_bitmask & (1 << 11)) != 0;
        let mode_raw = ((raw_button_bitmask >> 12) & 0x03) as u8;
        let mode_switch = RcSwitchMode::from_bits(mode_raw);
        let custom4_depressed = (raw_button_bitmask & (1 << 17)) != 0;
        let custom3_depressed = (raw_button_bitmask & (1 << 18)) != 0;
        let custom2_depressed = (raw_button_bitmask & (1 << 19)) != 0;
        let custom1_depressed = (raw_button_bitmask & (1 << 20)) != 0;
        let playback_depressed = (raw_button_bitmask & (1 << 21)) != 0;
        let shutter_depressed = (raw_button_bitmask & (1 << 22)) != 0;
        let record_depressed = (raw_button_bitmask & (1 << 23)) != 0;

        Ok(Self {
            raw_aileron,
            raw_elevator,
            raw_throttle,
            raw_rudder,
            raw_gyro,
            raw_button_bitmask,
            aileron,
            elevator,
            throttle,
            rudder,
            gyro,
            wheel_depressed,
            wheel_offset,
            signal_quality,
            go_home_depressed,
            mode_raw,
            mode_switch,
            custom4_depressed,
            custom3_depressed,
            custom2_depressed,
            custom1_depressed,
            playback_depressed,
            shutter_depressed,
            record_depressed,
        })
    }

    /// Aileron deflection percentage in `[-100, +100]`.
    #[inline]
    pub fn aileron_percent(&self) -> i8 {
        stick_percent(self.raw_aileron)
    }

    /// Elevator deflection percentage in `[-100, +100]`.
    #[inline]
    pub fn elevator_percent(&self) -> i8 {
        stick_percent(self.raw_elevator)
    }

    /// Throttle deflection percentage in `[-100, +100]`.
    #[inline]
    pub fn throttle_percent(&self) -> i8 {
        stick_percent(self.raw_throttle)
    }

    /// Rudder deflection percentage in `[-100, +100]`.
    #[inline]
    pub fn rudder_percent(&self) -> i8 {
        stick_percent(self.raw_rudder)
    }

    /// Returns `true` if all 4 flight control sticks are centered at neutral `1024` (or `0`).
    #[inline]
    pub fn is_neutral(&self) -> bool {
        (self.raw_aileron == STICK_CENTER || self.raw_aileron == 0)
            && (self.raw_elevator == STICK_CENTER || self.raw_elevator == 0)
            && (self.raw_throttle == STICK_CENTER || self.raw_throttle == 0)
            && (self.raw_rudder == STICK_CENTER || self.raw_rudder == 0)
    }

    /// Returns `true` if any customizable button (C1, C2, C3, C4) is pressed.
    #[inline]
    pub const fn any_custom_button_pressed(&self) -> bool {
        self.custom1_depressed
            || self.custom2_depressed
            || self.custom3_depressed
            || self.custom4_depressed
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_rc_neutral_and_disconnected() {
        // Neutral center: 1024 on all channels, bitmask = 0
        let mut payload = vec![0u8; 14];
        for i in 0..5 {
            payload[i * 2..i * 2 + 2].copy_from_slice(&1024i16.to_le_bytes());
        }
        let record = RcRecord::parse(&payload).expect("Must parse neutral RC");
        assert_eq!(record.aileron, 0.0);
        assert_eq!(record.elevator, 0.0);
        assert_eq!(record.throttle, 0.0);
        assert_eq!(record.rudder, 0.0);
        assert_eq!(record.gyro, 0.0);
        assert_eq!(record.aileron_percent(), 0);
        assert_eq!(record.elevator_percent(), 0);
        assert_eq!(record.throttle_percent(), 0);
        assert_eq!(record.rudder_percent(), 0);
        assert!(record.is_neutral());
        assert!(!is_stick_saturated(record.raw_aileron));

        // Disconnected channels: raw 0 -> must map to 1024 / 0.0
        let zero_payload = [0x00u8; 14];
        let zero_rec = RcRecord::parse(&zero_payload).expect("Must parse disconnected RC");
        assert_eq!(zero_rec.aileron, 0.0);
        assert_eq!(zero_rec.elevator, 0.0);
        assert_eq!(zero_rec.throttle, 0.0);
        assert_eq!(zero_rec.rudder, 0.0);
        assert_eq!(zero_rec.gyro, 0.0);
        assert!(zero_rec.is_neutral());
    }

    #[test]
    fn test_rc_cardinal_excursions() {
        let mut payload = vec![0u8; 14];
        payload[0..2].copy_from_slice(&1684i16.to_le_bytes()); // Aileron: +1.0
        payload[2..4].copy_from_slice(&364i16.to_le_bytes()); // Elevator: -1.0
        payload[4..6].copy_from_slice(&1684i16.to_le_bytes()); // Throttle: +1.0
        payload[6..8].copy_from_slice(&364i16.to_le_bytes()); // Rudder: -1.0
        payload[8..10].copy_from_slice(&1354i16.to_le_bytes()); // Gyro: +0.5

        let record = RcRecord::parse(&payload).expect("Must parse cardinal RC");
        assert!((record.aileron - 1.0).abs() < 1e-9);
        assert!((record.elevator - (-1.0)).abs() < 1e-9);
        assert!((record.throttle - 1.0).abs() < 1e-9);
        assert!((record.rudder - (-1.0)).abs() < 1e-9);
        assert!((record.gyro - 0.5).abs() < 1e-9);

        assert_eq!(record.aileron_percent(), 100);
        assert_eq!(record.elevator_percent(), -100);
        assert_eq!(record.throttle_percent(), 100);
        assert_eq!(record.rudder_percent(), -100);

        assert!(is_stick_saturated(record.raw_aileron));
        assert!(is_stick_saturated(record.raw_elevator));
        assert!(is_stick_saturated(record.raw_throttle));
        assert!(is_stick_saturated(record.raw_rudder));
        assert!(!is_stick_saturated(record.raw_gyro));
    }

    #[test]
    fn test_rc_button_bitmask_comprehensive() {
        let mut payload = vec![0u8; 14];
        for i in 0..5 {
            payload[i * 2..i * 2 + 2].copy_from_slice(&1024i16.to_le_bytes());
        }

        let bitmask: u32 = 0x00D6_281F;
        payload[10..14].copy_from_slice(&bitmask.to_le_bytes());

        let record = RcRecord::parse(&payload).expect("Must parse bitmask RC");
        assert!(record.wheel_depressed);
        assert_eq!(record.wheel_offset, 15);
        assert_eq!(record.signal_quality, 0x1F);
        assert!(record.go_home_depressed);
        assert_eq!(record.mode_raw, 2);
        assert_eq!(record.mode_switch, RcSwitchMode::Position2);
        assert!(record.custom4_depressed);
        assert!(!record.custom3_depressed);
        assert!(record.custom2_depressed);
        assert!(record.custom1_depressed);
        assert!(!record.playback_depressed);
        assert!(record.shutter_depressed);
        assert!(record.record_depressed);
        assert!(record.any_custom_button_pressed());
    }

    #[test]
    fn test_rc_out_of_bounds_extrapolation() {
        assert!(normalize_stick(1800) > 1.0);
        assert!(normalize_stick(200) < -1.0);
        assert_eq!(normalize_stick_clamped(1800), 1.0);
        assert_eq!(normalize_stick_clamped(200), -1.0);
    }

    #[test]
    fn test_rc_short_payload_tolerance() {
        let mut payload = vec![0u8; 10];
        for i in 0..5 {
            payload[i * 2..i * 2 + 2].copy_from_slice(&1024i16.to_le_bytes());
        }
        let record = RcRecord::parse(&payload).expect("Must parse 10-byte minimal RC");
        assert_eq!(record.aileron, 0.0);
        assert_eq!(record.raw_button_bitmask, 0);
        assert!(!record.wheel_depressed);
    }

    #[test]
    fn test_rc_truncated_rejection() {
        let payload = [0u8; 9];
        let err = RcRecord::parse(&payload).unwrap_err();
        match err {
            FlightReaderError::TruncatedRecord {
                expected,
                available,
            } => {
                assert_eq!(expected, 10);
                assert_eq!(available, 9);
            }
            other => panic!("Unexpected error: {:?}", other),
        }
    }
}

//! Battery & Smart Battery Telemetry Decoders for DJI `.txt` Flight Logs.
//!
//! Provides zero-allocation decoders for:
//! - Record Type 7 (`CenterBatteryFlightRecordDataType`): Disambiguates Variant A (Energy Summary)
//!   from Variant B (Individual Cell Voltage Array 1..=14).
//! - Record Type 8 (`PushedBatteryFlightRecordDataType`): Secondary pack telemetry on dual-battery craft.
//! - Record Type 22 (`SmartBatteryGroupDataType`): Battery health ledger, countdowns, warning bitmask.
//! - Record Type 6 (`MCTripodStateFlightRecordDataType`): Motorized landing gear state.
//! - Record Type 50 (`FlightRecordRecover`): Plaintext crash recovery packet with component serials.

use byteorder::{ByteOrder, LittleEndian};

use crate::error::{FlightReaderError, Result};

/// Sentinel constant representing uninitialized, unequipped, or missing telemetry values (-999.0).
pub const SENTINEL_UNINITIALIZED: f64 = -999.0;

/// Maximum number of individual cells supported in the raw cell array (cells 1 through 14).
pub const MAX_BATTERY_CELLS: usize = 14;

/// Minimum payload length in bytes for Record Type 7 / 8 Variant A (Energy Summary).
pub const VARIANT_A_MIN_LEN: usize = 10;

/// Minimum payload length in bytes for Record Type 7 / 8 Variant B (Cell Voltage Array).
pub const VARIANT_B_MIN_LEN: usize = 34;

/// Minimum payload length in bytes for Record Type 22 (Smart Battery Group).
pub const SMART_BATTERY_GROUP_MIN_LEN: usize = 29;

/// Minimum payload length in bytes for Record Type 6 (Tripod Landing Gear).
pub const TRIPOD_STATE_MIN_LEN: usize = 1;

/// Minimum payload length in bytes for Record Type 50 (Crash Recovery Packet).
pub const RECOVER_MIN_LEN: usize = 5;

/// Converts raw deci-Kelvin integer ($0.1\text{ K}$) to degrees Celsius (°C).
///
/// Returns [`SENTINEL_UNINITIALIZED`] if `raw <= 0` (indicating uninitialized sensor).
#[inline]
pub fn deci_kelvin_to_celsius(raw: i16) -> f64 {
    if raw <= 0 {
        SENTINEL_UNINITIALIZED
    } else {
        (raw as f64 / 10.0) - 273.15
    }
}

/// Converts degrees Celsius (°C) back to raw deci-Kelvin ($0.1\text{ K}$) for testing.
#[inline]
pub fn celsius_to_deci_kelvin(celsius: f64) -> i16 {
    ((celsius + 273.15) * 10.0).round() as i16
}

/// Normalizes raw battery current in milliamperes (mA) to Amperes (A).
///
/// Implements two's complement inversion when $val > 40.0\text{ A}$ per `CalculateBatteryCurrent`.
#[inline]
pub fn raw_current_to_amperes(raw: u16) -> f64 {
    let val = raw as f64 / 1000.0;
    if val > 40.0 {
        (65536.0 - raw as f64) / 1000.0
    } else {
        val
    }
}

// ============================================================================
// Record Type 7 / 8: Variant A (Energy Summary)
// ============================================================================

/// Energy summary battery telemetry packet (Record Type 7 / 8, Variant A).
///
/// Encapsulates State of Charge, total operational pack voltage, aggregate energy
/// capacities in milliampere-hours (mAh), cell count, pack temperature, and optional current draw.
#[derive(Debug, Clone, PartialEq)]
pub struct BatteryEnergySummary {
    /// State of Charge percentage (0..=100%).
    pub relative_capacity: u8,
    /// Total operational pack voltage in Volts (V).
    pub voltage: f64,
    /// Instantaneous remaining battery energy capacity in mAh.
    pub current_capacity_mah: u16,
    /// Full charge battery capacity in mAh at current health.
    pub full_capacity_mah: u16,
    /// Active number of cells in pack ($2 \dots 14$).
    pub cell_count: u8,
    /// Battery pack temperature reading in degrees Celsius (°C).
    pub temperature_celsius: f64,
    /// Optional instantaneous current draw in Amperes (A).
    pub current_draw_amperes: Option<f64>,
}

impl BatteryEnergySummary {
    /// Parses an Energy Summary packet from a raw payload slice.
    pub fn parse(payload: &[u8]) -> Result<Self> {
        if payload.len() < VARIANT_A_MIN_LEN {
            return Err(FlightReaderError::TruncatedRecord {
                expected: VARIANT_A_MIN_LEN,
                available: payload.len(),
            });
        }

        let relative_capacity = payload[0];
        let voltage = LittleEndian::read_u16(&payload[1..3]) as f64 / 1000.0;
        let current_capacity_mah = LittleEndian::read_u16(&payload[3..5]);
        let full_capacity_mah = LittleEndian::read_u16(&payload[5..7]);
        let cell_count = payload[7];
        let temperature_celsius = deci_kelvin_to_celsius(LittleEndian::read_i16(&payload[8..10]));

        let current_draw_amperes = if payload.len() >= 16 {
            Some(raw_current_to_amperes(LittleEndian::read_u16(
                &payload[14..16],
            )))
        } else if payload.len() >= 12 {
            Some(raw_current_to_amperes(LittleEndian::read_u16(
                &payload[10..12],
            )))
        } else {
            None
        };

        Ok(Self {
            relative_capacity,
            voltage,
            current_capacity_mah,
            full_capacity_mah,
            cell_count,
            temperature_celsius,
            current_draw_amperes,
        })
    }
}

// ============================================================================
// Record Type 7 / 8: Variant B (Raw Cell Voltage Array)
// ============================================================================

/// Individual cell voltage array telemetry packet (Record Type 7 / 8, Variant B).
///
/// Encapsulates individual cell voltages for up to 14 cells packed consecutively starting
/// at byte offset `3 + num32`. Unused or missing cells default to [`SENTINEL_UNINITIALIZED`] (`-999.0`).
#[derive(Debug, Clone, PartialEq)]
pub struct BatteryCellVoltages {
    /// State of Charge percentage (0..=100%).
    pub relative_capacity: u8,
    /// Total operational pack voltage in Volts (V).
    pub voltage: f64,
    /// Individual cell voltages in Volts for cells 1 through 14.
    /// Inactive or missing cells contain [`SENTINEL_UNINITIALIZED`] (`-999.0`).
    pub cell_voltages: [f64; MAX_BATTERY_CELLS],
    /// Active number of cells in pack ($2 \dots 14$).
    pub cell_count: u8,
    /// Battery pack temperature reading in degrees Celsius (°C).
    pub temperature_celsius: f64,
    /// Dynamic sub-header alignment offset detected (-1, 0, or 1).
    pub num32: i8,
}

impl BatteryCellVoltages {
    /// Parses a Raw Cell Voltage Array packet from a raw payload slice.
    pub fn parse(payload: &[u8]) -> Result<Self> {
        if payload.len() < VARIANT_B_MIN_LEN {
            return Err(FlightReaderError::TruncatedRecord {
                expected: VARIANT_B_MIN_LEN,
                available: payload.len(),
            });
        }

        let num32: i8 = if payload.len() == 33 {
            -1
        } else if payload.len() == 34 {
            0
        } else {
            1
        };

        let relative_capacity = payload[0];
        let voltage = LittleEndian::read_u16(&payload[1..3]) as f64 / 1000.0;

        let cell_count_idx = (31 + num32 as isize) as usize;
        let cell_count = if cell_count_idx < payload.len() {
            payload[cell_count_idx].min(MAX_BATTERY_CELLS as u8)
        } else {
            0
        };

        let temp_idx = (32 + num32 as isize) as usize;
        let temperature_celsius = if temp_idx + 2 <= payload.len() {
            deci_kelvin_to_celsius(LittleEndian::read_i16(&payload[temp_idx..temp_idx + 2]))
        } else {
            SENTINEL_UNINITIALIZED
        };

        let mut cell_voltages = [SENTINEL_UNINITIALIZED; MAX_BATTERY_CELLS];
        for k in 0..MAX_BATTERY_CELLS {
            let offset = (3 + num32 as isize + (2 * k as isize)) as usize;
            if offset + 2 <= payload.len() {
                let raw_mv = LittleEndian::read_u16(&payload[offset..offset + 2]);
                if (k as u8) < cell_count && raw_mv > 0 && raw_mv != 0xFFFF {
                    cell_voltages[k] = raw_mv as f64 / 1000.0;
                }
            }
        }

        Ok(Self {
            relative_capacity,
            voltage,
            cell_voltages,
            cell_count,
            temperature_celsius,
            num32,
        })
    }

    /// Returns the voltage of cell `cell_num` (1-indexed, 1..=14), or `None` if inactive/missing.
    pub fn cell_voltage(&self, cell_num: usize) -> Option<f64> {
        if (1..=MAX_BATTERY_CELLS).contains(&cell_num) {
            let val = self.cell_voltages[cell_num - 1];
            if (val - SENTINEL_UNINITIALIZED).abs() > 1e-3 {
                return Some(val);
            }
        }
        None
    }

    /// Returns the maximum voltage among active cells, or `None` if no cells active.
    pub fn max_cell_voltage(&self) -> Option<f64> {
        let count = self.cell_count as usize;
        self.cell_voltages[..count]
            .iter()
            .copied()
            .filter(|&v| (v - SENTINEL_UNINITIALIZED).abs() > 1e-3)
            .reduce(f64::max)
    }

    /// Returns the minimum voltage among active cells, or `None` if no cells active.
    pub fn min_cell_voltage(&self) -> Option<f64> {
        let count = self.cell_count as usize;
        self.cell_voltages[..count]
            .iter()
            .copied()
            .filter(|&v| (v - SENTINEL_UNINITIALIZED).abs() > 1e-3)
            .reduce(f64::min)
    }

    /// Returns maximum voltage deviation across active cells ($\max - \min$), or `None`.
    pub fn max_cell_deviation(&self) -> Option<f64> {
        match (self.max_cell_voltage(), self.min_cell_voltage()) {
            (Some(max_v), Some(min_v)) => Some(max_v - min_v),
            _ => None,
        }
    }
}

