/// Disambiguated battery telemetry record (Record Type 7 & 8).
#[derive(Debug, Clone, PartialEq)]
pub enum BatteryRecord {
    /// Variant A: Energy summary (capacity in mAh, pack voltage, SOC).
    EnergySummary(BatteryEnergySummary),
    /// Variant B: Individual cell voltage array (cells 1 through 14).
    CellVoltages(BatteryCellVoltages),
}

impl BatteryRecord {
    /// Parses Record Type 7 (Center Battery) or Record Type 8 (Pushed Battery).
    ///
    /// Automatically disambiguates Variant B (`payload.len() >= 34`) from Variant A (`< 34`).
    pub fn parse(payload: &[u8]) -> Result<Self> {
        if payload.len() >= VARIANT_B_MIN_LEN {
            BatteryCellVoltages::parse(payload).map(BatteryRecord::CellVoltages)
        } else {
            BatteryEnergySummary::parse(payload).map(BatteryRecord::EnergySummary)
        }
    }

    /// Returns the State of Charge percentage (0..=100%).
    pub fn relative_capacity(&self) -> u8 {
        match self {
            BatteryRecord::EnergySummary(s) => s.relative_capacity,
            BatteryRecord::CellVoltages(c) => c.relative_capacity,
        }
    }

    /// Returns the total pack operational voltage in Volts (V).
    pub fn voltage(&self) -> f64 {
        match self {
            BatteryRecord::EnergySummary(s) => s.voltage,
            BatteryRecord::CellVoltages(c) => c.voltage,
        }
    }

    /// Returns the active cell count in the pack.
    pub fn cell_count(&self) -> u8 {
        match self {
            BatteryRecord::EnergySummary(s) => s.cell_count,
            BatteryRecord::CellVoltages(c) => c.cell_count,
        }
    }

    /// Returns the battery pack temperature in degrees Celsius (°C).
    pub fn temperature_celsius(&self) -> f64 {
        match self {
            BatteryRecord::EnergySummary(s) => s.temperature_celsius,
            BatteryRecord::CellVoltages(c) => c.temperature_celsius,
        }
    }
}

/// Secondary battery telemetry record on dual-battery platforms (Record Type 8).
#[derive(Debug, Clone, PartialEq)]
pub struct PushedBatteryRecord(pub BatteryRecord);

impl PushedBatteryRecord {
    /// Parses a Record Type 8 secondary battery payload.
    pub fn parse(payload: &[u8]) -> Result<Self> {
        BatteryRecord::parse(payload).map(PushedBatteryRecord)
    }
}

