/// Motorized transformable landing gear operating states (Record Type 6).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum TripodStatus {
    /// Mechanism stationary / stopped.
    Stop,
    /// Landing gear deployed down for landing protection.
    DeformProtectClose,
    /// Landing gear raised open for unobstructed 360° gimbal rotation.
    DeformProtectOpen,
    /// Landing gear currently retracting / ascending.
    UpDeform,
    /// Travel / transport storage packaging mode.
    Pack,
    /// Unrecognized hardware status code.
    Other(u8),
}

/// Motorized transformable landing gear telemetry record (Record Type 6).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TripodStateRecord {
    /// Categorized landing gear status.
    pub status: TripodStatus,
    /// Raw status byte.
    pub raw_status: u8,
}

impl TripodStateRecord {
    /// Parses a Record Type 6 payload.
    pub fn parse(payload: &[u8]) -> Result<Self> {
        if payload.is_empty() {
            return Err(FlightReaderError::TruncatedRecord {
                expected: TRIPOD_STATE_MIN_LEN,
                available: 0,
            });
        }

        let raw_status = payload[0];
        let status = match raw_status {
            0 => TripodStatus::Stop,
            1 => TripodStatus::DeformProtectClose,
            2 => TripodStatus::DeformProtectOpen,
            3 => TripodStatus::UpDeform,
            4 => TripodStatus::Pack,
            other => TripodStatus::Other(other),
        };

        Ok(Self { status, raw_status })
    }
}

