// Record Type 50: FlightRecordRecover (Crash Recovery Packet)
// ============================================================================

/// Zero-allocation, fixed-capacity crash recovery record (Record Type 50).
///
/// Preserves component serial numbers, versions, and aircraft identifiers
/// emitted during sudden power-off or impact scenarios.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FlightRecordRecover {
    /// Drone model identifier code.
    pub drone_type: u8,
    /// Mobile application identifier code.
    pub app_type: u8,
    /// 3-part application version `[major, minor, patch]`.
    pub app_version: [u8; 3],
    /// Aircraft chassis serial number buffer.
    pub aircraft_serial: [u8; 16],
    /// Valid ASCII character count in `aircraft_serial`.
    pub aircraft_serial_len: u8,
    /// Aircraft user-assigned name buffer.
    pub aircraft_name: [u8; 32],
    /// Valid character count in `aircraft_name`.
    pub aircraft_name_len: u8,
    /// Camera payload serial number buffer.
    pub camera_serial: [u8; 16],
    /// Valid ASCII character count in `camera_serial`.
    pub camera_serial_len: u8,
    /// Remote controller serial number buffer.
    pub rc_serial: [u8; 16],
    /// Valid ASCII character count in `rc_serial`.
    pub rc_serial_len: u8,
    /// Battery pack serial number buffer.
    pub battery_serial: [u8; 16],
    /// Valid ASCII character count in `battery_serial`.
    pub battery_serial_len: u8,
    /// Gimbal hardware type code (if present).
    pub gimbal_type: Option<u8>,
    /// Whether modern (16-byte serials) or legacy (10-byte serials) format was detected.
    pub is_modern: bool,
}

impl FlightRecordRecover {
    /// Parses a Record Type 50 crash recovery payload.
    pub fn parse(payload: &[u8]) -> Result<Self> {
        if payload.len() < RECOVER_MIN_LEN {
            return Err(FlightReaderError::TruncatedRecord {
                expected: RECOVER_MIN_LEN,
                available: payload.len(),
            });
        }

        let drone_type = payload[0];
        let app_type = payload[1];
        let app_version = if payload.len() >= 5 {
            [payload[2], payload[3], payload[4]]
        } else {
            [0, 0, 0]
        };

        let is_modern = payload.len() >= 109;

        let mut aircraft_serial = [0u8; 16];
        let mut aircraft_serial_len = 0u8;
        let mut aircraft_name = [0u8; 32];
        let mut aircraft_name_len = 0u8;
        let mut camera_serial = [0u8; 16];
        let mut camera_serial_len = 0u8;
        let mut rc_serial = [0u8; 16];
        let mut rc_serial_len = 0u8;
        let mut battery_serial = [0u8; 16];
        let mut battery_serial_len = 0u8;

        if is_modern {
            // Modern layout (v12+)
            if payload.len() >= 21 {
                let slice = &payload[5..21.min(payload.len())];
                aircraft_serial_len = Self::sanitize_alphanumeric(slice, &mut aircraft_serial);
            }
            if payload.len() >= 53 {
                let slice = &payload[21..53.min(payload.len())];
                aircraft_name_len = Self::sanitize_printable(slice, &mut aircraft_name);
            }
            if payload.len() >= 77 {
                let slice = &payload[61..77.min(payload.len())];
                camera_serial_len = Self::sanitize_alphanumeric(slice, &mut camera_serial);
            }
            if payload.len() >= 93 {
                let slice = &payload[77..93.min(payload.len())];
                rc_serial_len = Self::sanitize_alphanumeric(slice, &mut rc_serial);
            }
            if payload.len() >= 109 {
                let slice = &payload[93..109.min(payload.len())];
                battery_serial_len = Self::sanitize_battery_serial(slice, &mut battery_serial);
            }
        } else {
            // Legacy layout
            if payload.len() >= 15 {
                let slice = &payload[5..15.min(payload.len())];
                aircraft_serial_len = Self::sanitize_alphanumeric(slice, &mut aircraft_serial);
            }
            if payload.len() >= 39 {
                let slice = &payload[15..39.min(payload.len())];
                aircraft_name_len = Self::sanitize_printable(slice, &mut aircraft_name);
            }
            if payload.len() >= 65 {
                let slice = &payload[55..65.min(payload.len())];
                camera_serial_len = Self::sanitize_alphanumeric(slice, &mut camera_serial);
            }
            if payload.len() >= 75 {
                let slice = &payload[65..75.min(payload.len())];
                rc_serial_len = Self::sanitize_alphanumeric(slice, &mut rc_serial);
            }
            if payload.len() >= 85 {
                let slice = &payload[75..85.min(payload.len())];
                battery_serial_len = Self::sanitize_battery_serial(slice, &mut battery_serial);
            }
        }

        let gimbal_type = if payload.len() >= 110 {
            Some(payload[109])
        } else {
            None
        };

        Ok(Self {
            drone_type,
            app_type,
            app_version,
            aircraft_serial,
            aircraft_serial_len,
            aircraft_name,
            aircraft_name_len,
            camera_serial,
            camera_serial_len,
            rc_serial,
            rc_serial_len,
            battery_serial,
            battery_serial_len,
            gimbal_type,
            is_modern,
        })
    }

    /// Filters and copies ASCII alphanumeric bytes into destination buffer.
    fn sanitize_alphanumeric(src: &[u8], dst: &mut [u8]) -> u8 {
        let mut count = 0usize;
        for &b in src {
            if count >= dst.len() {
                break;
            }
            if b.is_ascii_alphanumeric() {
                dst[count] = b;
                count += 1;
            } else if b == 0 {
                break;
            }
        }
        count as u8
    }

    /// Filters and copies printable ASCII bytes into destination buffer.
    fn sanitize_printable(src: &[u8], dst: &mut [u8]) -> u8 {
        let mut count = 0usize;
        for &b in src {
            if count >= dst.len() {
                break;
            }
            if (0x20..=0x7E).contains(&b) {
                dst[count] = b;
                count += 1;
            } else if b == 0 {
                break;
            }
        }
        count as u8
    }

    /// Sanitizes battery serial number, filtering out `"0000000000"`.
    fn sanitize_battery_serial(src: &[u8], dst: &mut [u8]) -> u8 {
        let len = Self::sanitize_alphanumeric(src, dst);
        let slice = &dst[..len as usize];
        if slice == b"0000000000" || slice.iter().all(|&b| b == b'0') {
            0
        } else {
            len
        }
    }

    /// Returns aircraft chassis serial number as a borrowed string slice.
    pub fn aircraft_serial_str(&self) -> &str {
        std::str::from_utf8(&self.aircraft_serial[..self.aircraft_serial_len as usize])
            .unwrap_or("")
    }

    /// Returns aircraft name as a borrowed string slice.
    pub fn aircraft_name_str(&self) -> &str {
        std::str::from_utf8(&self.aircraft_name[..self.aircraft_name_len as usize]).unwrap_or("")
    }

    /// Returns camera serial number as a borrowed string slice.
    pub fn camera_serial_str(&self) -> &str {
        std::str::from_utf8(&self.camera_serial[..self.camera_serial_len as usize]).unwrap_or("")
    }

    /// Returns remote controller serial number as a borrowed string slice.
    pub fn rc_serial_str(&self) -> &str {
        std::str::from_utf8(&self.rc_serial[..self.rc_serial_len as usize]).unwrap_or("")
    }

    /// Returns battery serial number as a borrowed string slice.
    pub fn battery_serial_str(&self) -> &str {
        std::str::from_utf8(&self.battery_serial[..self.battery_serial_len as usize]).unwrap_or("")
    }

    /// Returns formatted application version string e.g. `"4.3.2"`.
    pub fn app_version_string(&self) -> String {
        format!(
            "{}.{}.{}",
            self.app_version[0], self.app_version[1], self.app_version[2]
        )
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_variant_a_energy_summary_parsing() {
        let payload = [
            0x58, // RelativeCapacity: 88%
            0x60, 0x3B, // CurrentPV: 15200 mV -> 15.200 V
            0xD8, 0x0E, // CurrentCapacity: 3800 mAh
            0x94, 0x11, // FullCapacity: 4500 mAh
            0x04, // BatteryCellCount: 4
            0xA6, 0x0B, // BatteryTemperature: 2982 deci-K -> 25.05 °C
        ];

        let record = BatteryEnergySummary::parse(&payload).expect("Must parse Variant A");
        assert_eq!(record.relative_capacity, 88);
        assert!((record.voltage - 15.200).abs() < 1e-3);
        assert_eq!(record.current_capacity_mah, 3800);
        assert_eq!(record.full_capacity_mah, 4500);
        assert_eq!(record.cell_count, 4);
        assert!((record.temperature_celsius - 25.05).abs() < 1e-2);
        assert_eq!(record.current_draw_amperes, None);
    }

    #[test]
    fn test_variant_a_current_draw_and_twos_complement_inversion() {
        // Normal positive current: 6000 mA -> 6.0 A (len 16, offset 14..16)
        let mut payload = vec![0u8; 16];
        payload[0] = 80;
        LittleEndian::write_u16(&mut payload[1..3], 15000);
        LittleEndian::write_u16(&mut payload[14..16], 6000);

        let rec = BatteryEnergySummary::parse(&payload).unwrap();
        assert_eq!(rec.current_draw_amperes, Some(6.000));

        // 2's complement discharge inversion: 60000 -> 60.0 > 40.0 -> (65536 - 60000)/1000 = 5.536 A
        LittleEndian::write_u16(&mut payload[14..16], 60000);
        let rec2 = BatteryEnergySummary::parse(&payload).unwrap();
        assert!((rec2.current_draw_amperes.unwrap() - 5.536).abs() < 1e-3);
    }

    #[test]
    fn test_variant_b_cell_voltage_array_num32_zero() {
        let mut payload = vec![0u8; 34];
        payload[0] = 88; // SOC
        LittleEndian::write_u16(&mut payload[1..3], 15200); // 15.200 V
        LittleEndian::write_u16(&mut payload[3..5], 3800); // Cell 1
        LittleEndian::write_u16(&mut payload[5..7], 3805); // Cell 2
        LittleEndian::write_u16(&mut payload[7..9], 3795); // Cell 3
        LittleEndian::write_u16(&mut payload[9..11], 3800); // Cell 4
        payload[31] = 4; // cell_count
        LittleEndian::write_i16(&mut payload[32..34], 2982); // 25.05 °C

        let rec = BatteryCellVoltages::parse(&payload).expect("Must parse Variant B");
        assert_eq!(rec.num32, 0);
        assert_eq!(rec.cell_count, 4);
        assert_eq!(rec.cell_voltage(1), Some(3.800));
        assert_eq!(rec.cell_voltage(2), Some(3.805));
        assert_eq!(rec.cell_voltage(3), Some(3.795));
        assert_eq!(rec.cell_voltage(4), Some(3.800));
        assert_eq!(rec.cell_voltage(5), None);
        assert_eq!(rec.cell_voltages[4], SENTINEL_UNINITIALIZED);
        assert_eq!(rec.max_cell_voltage(), Some(3.805));
        assert_eq!(rec.min_cell_voltage(), Some(3.795));
        assert!((rec.max_cell_deviation().unwrap() - 0.010).abs() < 1e-4);
    }

    #[test]
    fn test_variant_b_alignment_offset_num32_one() {
        let mut payload = vec![0u8; 35];
        payload[0] = 75;
        LittleEndian::write_u16(&mut payload[1..3], 22800); // 22.800 V
        payload[3] = 0xAA; // Status prefix byte
        for k in 0..6 {
            LittleEndian::write_u16(&mut payload[4 + 2 * k..4 + 2 * k + 2], 3800);
        }
        payload[32] = 6; // cell_count
        LittleEndian::write_i16(&mut payload[33..35], 2992); // 26.05 °C

        let rec = BatteryCellVoltages::parse(&payload).expect("Must parse 35-byte Variant B");
        assert_eq!(rec.num32, 1);
        assert_eq!(rec.cell_count, 6);
        assert_eq!(rec.cell_voltage(1), Some(3.800));
        assert_eq!(rec.cell_voltage(6), Some(3.800));
        assert_eq!(rec.cell_voltage(7), None);
    }

    #[test]
    fn test_battery_record_disambiguation_enum() {
        // Variant A (< 34 bytes)
        let a_bytes = [0x50, 0x00, 0x30, 0x00, 0x10, 0x00, 0x20, 0x03, 0x00, 0x0A];
        let rec_a = BatteryRecord::parse(&a_bytes).expect("Must parse A");
        match rec_a {
            BatteryRecord::EnergySummary(s) => assert_eq!(s.relative_capacity, 0x50),
            _ => panic!("Expected EnergySummary"),
        }

        // Variant B (>= 34 bytes)
        let b_bytes = vec![0u8; 34];
        let rec_b = BatteryRecord::parse(&b_bytes).expect("Must parse B");
        match rec_b {
            BatteryRecord::CellVoltages(_) => {}
            _ => panic!("Expected CellVoltages"),
        }
    }

    #[test]
    fn test_smart_battery_group_parsing() {
        let mut payload = vec![0u8; 29];
        LittleEndian::write_u16(&mut payload[0..2], 1200);
        LittleEndian::write_u16(&mut payload[2..4], 300);
        LittleEndian::write_u16(&mut payload[4..6], 120);
        LittleEndian::write_u16(&mut payload[6..8], 25);
        LittleEndian::write_u16(&mut payload[8..10], 10);
        LittleEndian::write_f32(&mut payload[10..14], 1500.0);
        LittleEndian::write_f32(&mut payload[14..18], 2200.0);
        LittleEndian::write_u32(&mut payload[18..22], 0x00000002); // SMART_REQ_GO_HOME
        payload[22] = 1; // Executed
        payload[23] = 0; // Countdown
        LittleEndian::write_u16(&mut payload[24..26], 15100);
        payload[26] = 75; // 75%
        LittleEndian::write_u16(&mut payload[27..29], 0x8894);

        let group = SmartBatteryGroup::parse(&payload).expect("Must parse SmartBatteryGroup");
        assert_eq!(group.useful_time_secs, 1200);
        assert_eq!(group.go_home_time_secs, 300);
        assert_eq!(group.land_time_secs, 120);
        assert_eq!(group.go_home_battery_percent, 25);
        assert_eq!(group.land_battery_percent, 10);
        assert!((group.safe_fly_radius_m - 1500.0).abs() < 1e-2);
        assert!((group.volume_consume_mah - 2200.0).abs() < 1e-2);
        assert!(group.has_alert(smart_battery_alerts::SMART_REQ_GO_HOME));
        assert!(!group.has_alert(smart_battery_alerts::BATTERY_DANGEROUS));
        assert_eq!(group.go_home_status, SmartBatteryGoHomeStatus::Executed);
        assert_eq!(group.battery_percent, 75);
        assert_eq!(group.low_warning_percent, 20); // 0x94 & 0x7F = 20
        assert!(group.low_warning_go_home); // 0x94 & 0x80 != 0
        assert_eq!(group.serious_low_warning_percent, 8); // 0x88 & 0x7F = 8
        assert!(group.serious_low_warning_landing); // 0x8800 & 0x8000 != 0
    }

    #[test]
    fn test_tripod_state_parsing() {
        let p0 = [0u8];
        assert_eq!(
            TripodStateRecord::parse(&p0).unwrap().status,
            TripodStatus::Stop
        );

        let p1 = [1u8];
        assert_eq!(
            TripodStateRecord::parse(&p1).unwrap().status,
            TripodStatus::DeformProtectClose
        );

        let p2 = [2u8];
        assert_eq!(
            TripodStateRecord::parse(&p2).unwrap().status,
            TripodStatus::DeformProtectOpen
        );

        let p3 = [3u8];
        assert_eq!(
            TripodStateRecord::parse(&p3).unwrap().status,
            TripodStatus::UpDeform
        );

        let p4 = [4u8];
        assert_eq!(
            TripodStateRecord::parse(&p4).unwrap().status,
            TripodStatus::Pack
        );

        let p99 = [99u8];
        assert_eq!(
            TripodStateRecord::parse(&p99).unwrap().status,
            TripodStatus::Other(99)
        );

        assert!(TripodStateRecord::parse(&[]).is_err());
    }

    #[test]
    fn test_flight_record_recover_modern_parsing() {
        let mut payload = vec![0u8; 110];
        payload[0] = 18; // drone_type
        payload[1] = 1; // app_type
        payload[2..5].copy_from_slice(&[4, 3, 20]); // app_version
        payload[5..21].copy_from_slice(b"095XF1234567890A");
        payload[21..41].copy_from_slice(b"Matrice300RTK-Fleet1");
        payload[61..77].copy_from_slice(b"H20T998877665544");
        payload[77..93].copy_from_slice(b"RCPRO77889900112");
        payload[93..109].copy_from_slice(b"TB60112233445566");
        payload[109] = 3; // gimbal_type

        let rec = FlightRecordRecover::parse(&payload).expect("Must parse modern recover");
        assert!(rec.is_modern);
        assert_eq!(rec.aircraft_serial_str(), "095XF1234567890A");
        assert_eq!(rec.aircraft_name_str(), "Matrice300RTK-Fleet1");
        assert_eq!(rec.camera_serial_str(), "H20T998877665544");
        assert_eq!(rec.rc_serial_str(), "RCPRO77889900112");
        assert_eq!(rec.battery_serial_str(), "TB60112233445566");
        assert_eq!(rec.app_version_string(), "4.3.20");
        assert_eq!(rec.gimbal_type, Some(3));
    }

    #[test]
    fn test_flight_record_recover_battery_serial_zeroes_filtered() {
        let mut payload = vec![0u8; 110];
        payload[93..103].copy_from_slice(b"0000000000");
        let rec = FlightRecordRecover::parse(&payload).unwrap();
        assert_eq!(rec.battery_serial_str(), "");
    }
}

