#[test]
fn test_gimbal_modes_and_limits() {
    // 7-byte minimal payload: Pitch=-45.0°, Roll=10.0°, Yaw=90.0°
    // raw_pitch: -450 = 0xFE3E -> [0x3E, 0xFE]
    // raw_roll: 100 = 0x0064 -> [0x64, 0x00]
    // raw_yaw: 900 = 0x0384 -> [0x84, 0x03]
    // bitmask: 0x41 (Bit 0: Pitch limit, Bit 6: Stuck, Bits 6..7: FPV)
    let payload = [0x3E, 0xFE, 0x64, 0x00, 0x84, 0x03, 0x41];
    let gimbal = GimbalRecord::parse(&payload).expect("Must parse 7-byte Gimbal record");
    assert!((gimbal.pitch_deg - (-45.0)).abs() < 1e-5);
    assert!((gimbal.roll_deg - 10.0).abs() < 1e-5);
    assert!((gimbal.yaw_deg - 90.0).abs() < 1e-5);
    assert!((gimbal.yaw_360() - 90.0).abs() < 1e-5);
    assert!(gimbal.is_at_pitch_limit);
    assert!(!gimbal.is_at_roll_limit);
    assert!(!gimbal.is_at_yaw_limit);
    assert!(gimbal.is_at_any_limit());
    assert!(gimbal.is_stuck);
    assert_eq!(gimbal.mode, GimbalMode::Fpv);
    assert_eq!(gimbal.tilt_deg, None);
}

