#[test]
fn test_rc_full_deflection_and_switches() {
    let mut payload = vec![0u8; RC_STANDARD_PAYLOAD_LEN];
    LittleEndian::write_i16(&mut payload[0..2], STICK_MAX); // Aileron: +1.0
    LittleEndian::write_i16(&mut payload[2..4], STICK_MIN); // Elevator: -1.0
    LittleEndian::write_i16(&mut payload[4..6], STICK_MAX); // Throttle: +1.0
    LittleEndian::write_i16(&mut payload[6..8], STICK_MIN); // Rudder: -1.0
    LittleEndian::write_i16(&mut payload[8..10], 1354); // Gyro: +0.5

    // Bitmask construction:
    // Bit 0: wheel_depressed = 1
    // Bits 1..5: wheel_offset = 10 -> (10 << 1) = 20
    // Bit 11: go_home_depressed = 1 -> (1 << 11) = 0x0800
    // Bits 12..13: mode_raw = 1 (Sport) -> (1 << 12) = 0x1000
    // Bit 20: custom1_depressed = 1 -> (1 << 20) = 0x0010_0000
    // Bit 22: shutter_depressed = 1 -> (1 << 22) = 0x0040_0000
    // Bit 23: record_depressed = 1 -> (1 << 23) = 0x0080_0000
    let bitmask: u32 = 1 | 20 | 0x0800 | 0x1000 | 0x0010_0000 | 0x0040_0000 | 0x0080_0000;
    LittleEndian::write_u32(&mut payload[10..14], bitmask);

    let rc = RcRecord::parse(&payload).expect("Must parse deflected RC record");
    assert!((rc.aileron - 1.0).abs() < 1e-9);
    assert!((rc.elevator - (-1.0)).abs() < 1e-9);
    assert!((rc.throttle - 1.0).abs() < 1e-9);
    assert!((rc.rudder - (-1.0)).abs() < 1e-9);
    assert!((rc.gyro - 0.5).abs() < 1e-9);
    assert_eq!(rc.aileron_percent(), 100);
    assert_eq!(rc.elevator_percent(), -100);

    assert!(is_stick_saturated(rc.raw_aileron));
    assert!(is_stick_saturated(rc.raw_elevator));
    assert!(!is_stick_saturated(rc.raw_gyro));

    assert!(rc.wheel_depressed);
    assert_eq!(rc.wheel_offset, 10);
    assert!(rc.go_home_depressed);
    assert_eq!(rc.mode_raw, 1);
    assert_eq!(rc.mode_switch, RcSwitchMode::Position1);
    assert!(rc.custom1_depressed);
    assert!(!rc.custom2_depressed);
    assert!(rc.any_custom_button_pressed());
    assert!(rc.shutter_depressed);
    assert!(rc.record_depressed);
}

