#[test]
fn test_battery_variant_a_energy_summary_and_current_inversion() {
    let mut payload = vec![0u8; 16];
    payload[0] = 92; // 92% SOC
    LittleEndian::write_u16(&mut payload[1..3], 15200); // 15.200 V
    LittleEndian::write_u16(&mut payload[3..5], 4000); // 4000 mAh
    LittleEndian::write_u16(&mut payload[5..7], 4500); // 4500 mAh
    payload[7] = 4; // 4 cells
    LittleEndian::write_i16(&mut payload[8..10], 2982); // 25.05 °C
    LittleEndian::write_u16(&mut payload[14..16], 62000); // 2's complement discharge

    let rec = BatteryRecord::parse(&payload).expect("Must parse Variant A");
    assert_eq!(rec.relative_capacity(), 92);
    assert!((rec.voltage() - 15.200).abs() < 1e-3);
    assert_eq!(rec.cell_count(), 4);
    assert!((rec.temperature_celsius() - 25.05).abs() < 1e-2);

    match rec {
        BatteryRecord::EnergySummary(s) => {
            assert_eq!(s.current_capacity_mah, 4000);
            assert_eq!(s.full_capacity_mah, 4500);
            // 62000 / 1000 = 62.0 > 40.0 -> (65536 - 62000) / 1000 = 3.536 A
            assert!((s.current_draw_amperes.unwrap() - 3.536).abs() < 1e-3);
        }
        _ => panic!("Expected EnergySummary"),
    }
}

