#[test]
fn test_smart_battery_group_record_type_22() {
    let mut payload = vec![0u8; SMART_BATTERY_GROUP_MIN_LEN];
    LittleEndian::write_u16(&mut payload[0..2], 1500); // useful time
    LittleEndian::write_u16(&mut payload[2..4], 400); // go home time
    LittleEndian::write_u16(&mut payload[4..6], 150); // land time
    LittleEndian::write_u16(&mut payload[6..8], 30); // go home %
    LittleEndian::write_u16(&mut payload[8..10], 15); // land %
    LittleEndian::write_f32(&mut payload[10..14], 2500.0); // radius
    LittleEndian::write_f32(&mut payload[14..18], 3100.0); // volume
    LittleEndian::write_u32(
        &mut payload[18..22],
        smart_battery_alerts::BATTERY_CELL_ERROR,
    );
    payload[22] = 0; // Countdown status
    payload[23] = 10; // 10s countdown
    LittleEndian::write_u16(&mut payload[24..26], 15300);
    payload[26] = 80;
    // warning word: low warning 25% (GoHome=false), serious low 12% (Landing=true)
    // 25 = 0x19; 12 = 0x0C; landing = 0x8000 -> 0x8C19
    LittleEndian::write_u16(&mut payload[27..29], 0x8C19);

    let group = SmartBatteryGroup::parse(&payload).expect("Must parse SmartBatteryGroup");
    assert_eq!(group.useful_time_secs, 1500);
    assert_eq!(group.go_home_time_secs, 400);
    assert_eq!(group.land_time_secs, 150);
    assert_eq!(group.go_home_battery_percent, 30);
    assert_eq!(group.land_battery_percent, 15);
    assert_eq!(group.safe_fly_radius_m, 2500.0);
    assert_eq!(group.volume_consume_mah, 3100.0);
    assert!(group.has_alert(smart_battery_alerts::BATTERY_CELL_ERROR));
    assert!(!group.has_alert(smart_battery_alerts::BATTERY_DANGEROUS));
    assert_eq!(
        group.go_home_status,
        SmartBatteryGoHomeStatus::CountingDown
    );
    assert_eq!(group.go_home_countdown, 10);
    assert_eq!(group.battery_percent, 80);
    assert_eq!(group.low_warning_percent, 25);
    assert!(!group.low_warning_go_home);
    assert_eq!(group.serious_low_warning_percent, 12);
    assert!(group.serious_low_warning_landing);
}

